const app = document.querySelector('#app');
const toastRegion = document.querySelector('#toast-region');
const importInput = document.querySelector('#import-file');
const state = { user: null, workspaces: [], workspaceId: localStorage.getItem('archflow.workspace') || '', route: location.pathname, projects: [], project: null, editor: null, modal: null, dashboardQuery: '', dashboardSort: 'recent', dashboardArchived: false, pendingRoute: null };

class ApiError extends Error { constructor(message, status, code, payload) { super(message); this.status=status; this.code=code; this.payload=payload; } }
async function api(path, options={}) {
  const init={credentials:'same-origin',...options,headers:{...(options.body?{'content-type':'application/json'}:{}),...(options.headers||{})}};
  if(init.body && typeof init.body!=='string') init.body=JSON.stringify(init.body);
  const response=await fetch(path,init); let payload={}; try{payload=await response.json();}catch{}
  if(!response.ok) throw new ApiError(payload.error?.message||`Request failed (${response.status})`,response.status,payload.error?.code,payload);
  return payload;
}
const h=(value='')=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
const clone=(value)=>JSON.parse(JSON.stringify(value));
const dateShort=(value)=>value?new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric'}).format(new Date(value)):'—';
const dateTime=(value)=>value?new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(value)):'—';
const initials=(name='A')=>String(name).split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase();
function toast(message,type='') { const item=document.createElement('div'); item.className=`toast ${type}`; item.textContent=message; toastRegion.append(item); setTimeout(()=>item.remove(),3700); }
function setRoute(path,replace=false){state.route=path;history[replace?'replaceState':'pushState']({},'',path);renderRoute();}
window.addEventListener('popstate',()=>{state.route=location.pathname;renderRoute();});

function brand(light=false){return `<span class="brand ${light?'wordmark-light':''}"><span class="brand-mark">A</span><span>archflow</span></span>`;}
function landing(){return `<div class="landing"><nav class="landing-nav">${brand()}<div class="landing-nav-actions"><button class="btn btn-secondary" data-action="signin">Sign in</button><button class="btn btn-primary" data-action="signup">Create your workspace <span aria-hidden="true">→</span></button></div></nav><main class="landing-main"><section class="hero"><div class="hero-copy"><div class="eyebrow">Architecture, made clear</div><h1>Make complex systems <span>make sense.</span></h1><p>Bring your architecture out of the whiteboard and into a shared, living workspace. Design, document, and align your team on the systems you build.</p><div class="hero-ctas"><button class="btn btn-primary" data-action="signup">Start designing for free <span aria-hidden="true">→</span></button><button class="btn btn-secondary" data-action="demo-login"><span class="icon">◫</span> Explore the demo</button></div><div class="hero-note"><span class="check">✓</span> No credit card needed <span>·</span> Your work stays yours</div></div><div class="hero-art" aria-label="Sample architecture diagram preview"><div class="hero-window"><div class="hero-window-head"><i class="hero-dot"></i><i class="hero-dot"></i><i class="hero-dot"></i><span class="hero-window-title">Northstar Commerce · Global storefront</span></div><div class="hero-diagram"><i class="hero-edge" style="left:21%;top:49%;width:19%;transform:rotate(0deg)"></i><i class="hero-edge" style="left:40%;top:49%;width:19%;transform:rotate(-15deg)"></i><i class="hero-edge" style="left:59%;top:44%;width:17%;transform:rotate(0deg)"></i><div class="hero-node" style="left:4%;top:36%"><i>◉</i><strong>Customers</strong></div><div class="hero-node" style="left:23%;top:36%"><i>⌁</i><strong>CloudFront CDN</strong></div><div class="hero-node" style="left:42%;top:36%"><i>⇄</i><strong>Edge API</strong></div><div class="hero-node" style="left:61%;top:18%"><i>◇</i><strong>Catalog service</strong></div><div class="hero-node" style="left:61%;top:55%"><i>▤</i><strong>Orders database</strong></div><div class="hero-node" style="left:80%;top:55%"><i>⇢</i><strong>Events queue</strong></div></div></div><div class="hero-pill">● Saved just now</div></div></section><section class="feature-row"><article class="feature"><div class="feature-icon">⌘</div><h3>Think in systems</h3><p>Map services, data, and infrastructure on a canvas that stays clear as your architecture grows.</p></article><article class="feature"><div class="feature-icon">↗</div><h3>Keep everyone aligned</h3><p>Give teammates a shared source of truth with clear ownership, access, and project history.</p></article><article class="feature"><div class="feature-icon">▤</div><h3>Document as you design</h3><p>Capture decisions, properties, and connections alongside the diagram—not in a separate doc.</p></article></section></main></div>`;}

function authPage(mode){const recovery=mode==='forgot';const signup=mode==='signup';return `<div class="auth-shell"><aside class="auth-side"><a href="/">${brand()}</a><div class="auth-side-copy"><div class="eyebrow">A calmer way to architect</div><h1>Design with clarity.<br>Build with confidence.</h1><p>From the first service boundary to the production topology, keep your system design connected to the people who build it.</p></div><div class="auth-side-foot">© 2026 Archflow · Designed for the teams behind the systems</div></aside><main class="auth-form-wrap"><form class="auth-form" data-form="${recovery?'forgot':signup?'signup':'signin'}"><button type="button" class="btn btn-quiet btn-small" data-action="home" style="margin-bottom:25px">← Back to home</button><h2>${recovery?'Reset your password':signup?'Create your account':'Welcome back'}</h2><p>${recovery?'Enter the email on your account and we’ll send a secure reset link.':signup?'Start a workspace for your team. Your first project is a few clicks away.':'Sign in to continue to your architecture workspace.'}</p><div class="form-feedback" aria-live="polite"></div>${signup?`<div class="field"><label for="auth-name">Your name</label><input id="auth-name" name="name" autocomplete="name" required maxlength="80" placeholder="Alex Morgan"></div>`:''}<div class="field"><label for="auth-email">Work email</label><input id="auth-email" name="email" type="email" autocomplete="email" required placeholder="you@company.com"></div>${!recovery?`<div class="field"><label for="auth-password">Password</label><input id="auth-password" name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" required minlength="${signup?10:1}" placeholder="${signup?'At least 10 characters':'Enter your password'}"></div>`:''}${!signup&&!recovery?`<div style="text-align:right;margin:-7px 0 17px"><button type="button" class="text-link" data-action="forgot" style="border:0;background:none;font-size:11px;padding:0">Forgot password?</button></div>`:''}<button class="btn btn-primary" type="submit" style="width:100%">${recovery?'Send reset link':signup?'Create account':'Sign in'} <span aria-hidden="true">→</span></button><div class="form-footer">${recovery?`Remembered it? <button type="button" class="text-link" data-action="signin" style="border:0;background:none">Sign in</button>`:signup?`Already have an account? <button type="button" class="text-link" data-action="signin" style="border:0;background:none">Sign in</button>`:`New to Archflow? <button type="button" class="text-link" data-action="signup" style="border:0;background:none">Create an account</button>`}</div>${!signup&&!recovery?`<div class="demo-access"><span>◉</span><span>Evaluating the app? <button type="button" class="text-link" data-action="demo-login" style="border:0;background:none">Open the demo workspace</button></span></div>`:''}</form></main></div>`;}

function sidebar(active='overview'){const ws=state.workspaces.find(w=>w.id===state.workspaceId);return `<aside class="sidebar">${brand()}<button class="workspace-switch" data-action="workspace-menu"><span class="workspace-avatar">${h(initials(ws?.name||'A'))}</span><span class="workspace-names"><strong>${h(ws?.name||'Workspace')}</strong><small>${h(ws?.role||'Owner')} workspace</small></span><span class="muted">⌄</span></button><div class="sidebar-label">Workspace</div><button class="side-link ${active==='overview'?'active':''}" data-action="dashboard"><span class="icon">▦</span><span>Overview</span></button><button class="side-link ${active==='archive'?'active':''}" data-action="archive"><span class="icon">▣</span><span>Archived</span></button><div class="sidebar-spacer"></div><div class="sidebar-bottom"><button class="side-link ${active==='settings'?'active':''}" data-action="settings"><span class="icon">⚙</span><span>Workspace settings</span></button><button class="side-link" data-action="help"><span class="icon">?</span><span>Help & shortcuts</span></button><div class="user-card"><span class="user-avatar">${h(initials(state.user?.name))}</span><span class="user-info"><strong>${h(state.user?.name)}</strong><small>${h(state.user?.email)}</small></span><button class="btn-icon" title="Account settings" aria-label="Account settings" data-action="settings">⚙</button></div></div></aside>`;}
function shell(content,{active='overview',crumb='Overview',actions='',wide=false}={}){return `<div class="app-shell">${sidebar(active)}<div class="app-main"><header class="topbar"><div class="breadcrumbs"><span>${h(state.workspaces.find(w=>w.id===state.workspaceId)?.name||'Workspace')}</span><span>›</span><strong>${h(crumb)}</strong></div><div class="top-actions">${actions}<button class="btn-icon" title="Account" aria-label="Account settings" data-action="settings">${h(initials(state.user?.name))}</button></div></header>${content}</div></div>`;}

async function ensureSession(){if(state.user)return true;try{const result=await api('/api/me');state.user=result.user;state.workspaces=result.workspaces||[];if(!state.workspaces.some(w=>w.id===state.workspaceId))state.workspaceId=state.workspaces[0]?.id||'';if(state.workspaceId)localStorage.setItem('archflow.workspace',state.workspaceId);return true;}catch(e){if(e.status===401)return false;throw e;}}
async function renderRoute(){try{
  state.route=location.pathname;
  const route=state.route;
  if(route==='/signin'||route==='/signup'||route==='/forgot'||route==='/reset'){
    if(route==='/reset'){renderResetPage();return;}
    app.innerHTML=authPage(route.slice(1));return;
  }
  if(route.startsWith('/share/')){await renderSharePage(route.split('/')[2]);return;}
  if(route.startsWith('/invite/')){await renderInvitePage(route.split('/')[2]);return;}
  const hasSession=await ensureSession();
  if(!hasSession){app.innerHTML=landing();return;}
  if(route.startsWith('/diagram/')){await renderEditor(route.split('/')[2]);return;}
  if(route.startsWith('/project/')){await renderProject(route.split('/')[2]);return;}
  if(route==='/settings'){await renderSettings();return;}
  if(route==='/archive'){state.dashboardArchived=true;await renderDashboard();return;}
  state.dashboardArchived=false;await renderDashboard();
}catch(error){app.innerHTML=`<div class="page-loading"><div class="empty-icon">!</div><p>${h(error.message||'Unable to load this page.')}</p><button class="btn btn-secondary" data-action="dashboard">Return to workspace</button></div>`;}}

async function renderDashboard(){
  if(!state.workspaceId){app.innerHTML=`<div class="page-loading">No workspace found. <button class="btn btn-primary" data-action="create-workspace">Create a workspace</button></div>`;return;}
  app.innerHTML=shell(`<main class="content"><div class="page-loading"><div class="spinner"></div>Loading your workspace…</div></main>`,{active:state.dashboardArchived?'archive':'overview',crumb:state.dashboardArchived?'Archived projects':'Overview'});
  const params=new URLSearchParams({workspaceId:state.workspaceId,q:state.dashboardQuery,sort:state.dashboardSort,archived:String(state.dashboardArchived),page:'1',limit:'50'});
  const result=await api(`/api/projects?${params}`);state.projects=result.projects;
  const totalDiagrams=state.projects.reduce((sum,p)=>sum+p.diagramCount,0);
  const action=`<div class="searchbox"><span class="search-icon">⌕</span><input data-input="dashboard-search" aria-label="Search projects" placeholder="Search projects…" value="${h(state.dashboardQuery)}"></div><button class="btn btn-primary btn-small" data-action="new-project"><span class="icon">＋</span> New project</button>`;
  const cards=state.projects.map(p=>`<article class="project-card" tabindex="0" data-action="open-project" data-id="${p.id}"><div class="project-card-top"><span class="project-glyph">◇</span><button class="project-more" aria-label="Project options" data-action="project-menu" data-id="${p.id}">•••</button></div><h3>${h(p.name)}</h3><p>${h(p.description||'A place for architecture diagrams and decisions.')}</p><div class="tag-list">${p.tags.slice(0,3).map(t=>`<span class="tag">${h(t)}</span>`).join('')}${p.tags.length>3?`<span class="tag">+${p.tags.length-3}</span>`:''}</div><div class="project-card-foot"><span>${p.diagramCount} ${p.diagramCount===1?'diagram':'diagrams'}</span><span>Edited ${dateShort(p.updatedAt)}</span></div></article>`).join('');
  const content=`<main class="content"><div class="welcome-row"><div><div class="eyebrow">${state.dashboardArchived?'Project archive':'Workspace overview'}</div><h1>${state.dashboardArchived?'Archived projects':`Good ${greeting()}, ${h(state.user.name.split(' ')[0])}`}</h1><p>${state.dashboardArchived?'Restore projects when your team is ready to work on them again.':'Your team’s architecture work, in one clear place.'}</p></div>${!state.dashboardArchived?`<button class="btn btn-primary" data-action="new-project"><span class="icon">＋</span> New project</button>`:''}</div>${!state.dashboardArchived?`<div class="stats-row"><div class="stat-card"><div><small>Active projects</small><strong>${result.total}</strong></div><span class="stat-icon">◇</span></div><div class="stat-card"><div><small>Diagrams</small><strong>${totalDiagrams}</strong></div><span class="stat-icon">⌘</span></div><div class="stat-card"><div><small>Workspace role</small><strong style="font-size:17px">${h(state.workspaces.find(w=>w.id===state.workspaceId)?.role||'Owner')}</strong></div><span class="stat-icon">♧</span></div></div>`:''}<div class="section-heading"><h2>${state.dashboardArchived?'Archived projects':'Recent projects'}</h2><div style="display:flex;align-items:center;gap:10px"><select class="input" data-input="project-sort" aria-label="Sort projects" style="width:auto;padding:6px 9px;font-size:10px"><option value="recent" ${state.dashboardSort==='recent'?'selected':''}>Recently edited</option><option value="name" ${state.dashboardSort==='name'?'selected':''}>Name A–Z</option></select><span>${result.total} ${result.total===1?'project':'projects'}</span></div></div>${cards?`<div class="project-grid">${cards}</div>`:state.dashboardQuery?`<div class="empty-state"><div class="empty-icon">⌕</div><h3>No projects match “${h(state.dashboardQuery)}”</h3><p>Try a different name or search term.</p><button class="btn btn-secondary btn-small" data-action="clear-search">Clear search</button></div>`:`<div class="empty-state"><div class="empty-icon">◇</div><h3>${state.dashboardArchived?'Nothing in the archive':'Start with your first project'}</h3><p>${state.dashboardArchived?'Archived projects will show here when you need them.':'Create a project to organize diagrams, document decisions, and invite your team.'}</p>${state.dashboardArchived?'':`<button class="btn btn-primary btn-small" data-action="new-project">Create a project</button>`}</div>`}<div class="section-heading" style="margin-top:32px"><h2>Quick start</h2><span>Make progress in a few clicks</span></div><div class="notice-card"><strong>Start from a proven architecture.</strong> Create a blank canvas or use a web application, microservices, or data pipeline template. <button class="text-link" data-action="new-project" style="border:0;background:none">Create a project →</button></div></main>`;
  app.innerHTML=shell(content,{active:state.dashboardArchived?'archive':'overview',crumb:state.dashboardArchived?'Archived projects':'Overview',actions:action});
  if(!canEditWorkspace())document.querySelectorAll('[data-action="new-project"]').forEach(b=>b.disabled=true);
}
function greeting(){const hour=new Date().getHours();return hour<12?'morning':hour<18?'afternoon':'evening';}
function canEditWorkspace(){return ['Owner','Editor'].includes(state.workspaces.find(w=>w.id===state.workspaceId)?.role);}

async function renderProject(projectId){
  app.innerHTML=shell(`<main class="content"><div class="page-loading"><div class="spinner"></div>Loading project…</div></main>`,{crumb:'Project'});
  const result=await api(`/api/projects/${projectId}`);state.project=result.project;
  const diagrams=result.diagrams;
  const cards=diagrams.map((d,i)=>`<article class="diagram-card" tabindex="0" data-action="open-diagram" data-id="${d.id}"><div class="diagram-preview">${[0,1,2,3,4].map((n)=>`<i class="preview-box" style="left:${12+n*16}%;top:${n%2?26:53}%;width:${n%2?31:28}px;height:18px"></i>`).join('')}<i class="preview-wire" style="left:20%;top:61%;width:62%;transform:rotate(-4deg)"></i></div><div class="diagram-card-body"><h3>${h(d.name)}</h3><p>Edited ${dateShort(d.updatedAt)} · Revision ${d.revision}</p></div></article>`).join('');
  const content=`<main class="content"><div style="margin-bottom:17px"><button class="btn btn-quiet btn-small" data-action="dashboard">← All projects</button></div><div class="project-header"><div><div class="eyebrow">Project · ${h(state.workspaces.find(w=>w.id===state.workspaceId)?.name||'Workspace')}</div><h1>${h(result.project.name)}</h1><p>${h(result.project.description||'Add a short description to help your team understand this project.')}</p><div class="tag-list" style="margin:12px 0 0">${result.project.tags.map(t=>`<span class="tag">${h(t)}</span>`).join('')}</div><div class="project-meta"><span>Owner: ${h(result.project.ownerName||'Unknown')}</span><span>Updated ${dateTime(result.project.updatedAt)}</span></div></div><div class="project-actions"><button class="btn btn-secondary btn-small" data-action="edit-project" data-id="${result.project.id}">⚙ Project settings</button><button class="btn btn-primary btn-small" data-action="new-diagram" data-id="${result.project.id}"><span class="icon">＋</span> New diagram</button></div></div><div class="section-heading"><h2>Diagrams</h2><span>${diagrams.length} ${diagrams.length===1?'diagram':'diagrams'}</span></div>${cards?`<div class="diagram-grid">${cards}</div>`:`<div class="empty-state"><div class="empty-icon">⌘</div><h3>Your canvas is ready</h3><p>Create a diagram from scratch or use a template for a web application, microservices platform, or data pipeline.</p><button class="btn btn-primary btn-small" data-action="new-diagram" data-id="${result.project.id}">Create your first diagram</button></div>`}</main>`;
  const actions=`<button class="btn btn-secondary btn-small" data-action="duplicate-project" data-id="${result.project.id}">Duplicate</button><button class="btn btn-secondary btn-small" data-action="project-overflow" data-id="${result.project.id}">•••</button>`;
  app.innerHTML=shell(content,{crumb:result.project.name,actions});
  if(!canEditWorkspace())document.querySelectorAll('[data-action="edit-project"],[data-action="new-diagram"],[data-action="duplicate-project"],[data-action="project-overflow"]').forEach(b=>b.disabled=true);
}

function modal(title,subtitle,body,foot=''){app.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" role="presentation" data-action="backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><div><h2 id="modal-title">${h(title)}</h2>${subtitle?`<p>${h(subtitle)}</p>`:''}</div><button class="btn-icon" aria-label="Close dialog" data-action="close-modal">×</button></header><div class="modal-content">${body}</div>${foot?`<footer class="modal-foot">${foot}</footer>`:''}</section></div>`);state.modal=app.querySelector('.modal-backdrop');state.modal.querySelector('input,button,textarea,select')?.focus();}
function closeModal(){const stack=app.querySelectorAll('.modal-backdrop');stack[stack.length-1]?.remove();const remaining=app.querySelectorAll('.modal-backdrop');state.modal=remaining[remaining.length-1]||null;}
function projectForm(p={}){return `<form data-form="project"><input type="hidden" name="id" value="${h(p.id||'')}"><div class="field"><label>Project name</label><input name="name" maxlength="120" required value="${h(p.name||'')}"></div><div class="field"><label>Description</label><textarea name="description" maxlength="2000" placeholder="What system or product does this project cover?">${h(p.description||'')}</textarea></div><div class="field"><label>Tags</label><input name="tags" value="${h((p.tags||[]).join(', '))}" placeholder="e.g. AWS, production, payments"><span class="field-hint">Separate tags with commas.</span></div><div class="form-feedback"></div><div class="modal-foot" style="padding:8px 0 0"><button type="button" class="btn btn-secondary btn-small" data-action="close-modal">Cancel</button><button class="btn btn-primary btn-small" type="submit">${p.id?'Save changes':'Create project'}</button></div></form>`;}

function openCreateProject(){modal('Create a project','Group diagrams and design notes around one system.',projectForm());}
function openEditProject(){modal('Project settings','Update the details your team sees.',projectForm(state.project));}
function openTemplateModal(projectId){const templates=[['blank','Blank canvas','A clean starting point'],['web','Three-tier web app','Client, API, and data layer'],['microservices','Microservices platform','Services, events, and storage'],['pipeline','Data pipeline','Ingestion through analytics']];const body=`<div class="template-grid">${templates.map(([id,name,desc],i)=>`<button class="template-card" data-action="choose-template" data-id="${id}" data-project="${projectId}"><div class="template-art">${Array.from({length:i===0?0:4},(_,j)=>`<i class="template-chip" style="left:${12+j*20}%;top:${j%2?48:19}%"></i>`).join('')}</div><strong>${name}</strong><small>${desc}</small></button>`).join('')}</div><div class="field" style="margin-top:16px;margin-bottom:0"><label>Diagram name</label><input id="new-diagram-name" maxlength="120" value="Untitled diagram"></div>`;modal('Choose a starting point','You can change every component and connection after creation.',body);}

function workspaceMenu(){const options=state.workspaces.map(w=>`<button data-action="switch-workspace" data-id="${w.id}"><strong>${h(w.name)}</strong><small style="display:block;color:#87958e;margin-top:3px">${h(w.role)}</small></button>`).join('');modal('Your workspaces','Move between teams without leaving your architecture work.',`${options}<div style="border-top:1px solid #edf1ee;padding-top:10px;margin-top:8px"><button class="btn btn-secondary btn-small" data-action="create-workspace">＋ New workspace</button></div>`);}
function openProjectMenu(projectId){const p=state.projects.find(x=>x.id===projectId)||(state.project?.id===projectId?state.project:null);if(!p){return;}const archived=p.archived,role=state.workspaces.find(w=>w.id===state.workspaceId)?.role;modal('Project actions',p.name,`<div style="display:grid;gap:8px"><button class="btn btn-secondary" data-action="edit-project" data-id="${p.id}" ${canEditWorkspace()?'':'disabled'}>✎ Edit details</button><button class="btn btn-secondary" data-action="duplicate-project" data-id="${p.id}" ${canEditWorkspace()?'':'disabled'}>▣ Duplicate project</button>${role==='Owner'?`<button class="btn btn-secondary" data-action="${archived?'restore-project':'archive-project'}" data-id="${p.id}">${archived?'↶ Restore project':'▣ Archive project'}</button><button class="btn btn-danger" data-action="delete-project" data-id="${p.id}">Delete project</button>`:''}</div>`);}

async function renderSettings(){
  app.innerHTML=shell(`<main class="content"><div class="page-loading"><div class="spinner"></div>Loading settings…</div></main>`,{active:'settings',crumb:'Settings'});
  const [members,projects]=await Promise.all([api(`/api/workspaces/${state.workspaceId}/members`),api(`/api/projects?workspaceId=${state.workspaceId}&limit=1`)]);
  const role=state.workspaces.find(w=>w.id===state.workspaceId)?.role||'Viewer';
  const memberHtml=members.members.map(m=>`<div class="member-row"><span class="user-avatar">${h(initials(m.name))}</span><span class="member-info"><strong>${h(m.name)} ${m.id===state.user.id?'<span class="muted">(you)</span>':''}</strong><small>${h(m.email)}</small></span>${role==='Owner'&&m.id!==state.user.id?`<select data-input="member-role" data-id="${m.id}" aria-label="Role for ${h(m.name)}"><option ${m.role==='Editor'?'selected':''}>Editor</option><option ${m.role==='Viewer'?'selected':''}>Viewer</option><option ${m.role==='Owner'?'selected':''}>Owner</option></select><button class="btn-icon" data-action="remove-member" data-id="${m.id}" title="Remove member" aria-label="Remove ${h(m.name)}">×</button>`:`<span class="tag">${h(m.role)}</span>`}</div>`).join('');
  const content=`<main class="content"><div class="welcome-row"><div><div class="eyebrow">${h(state.workspaces.find(w=>w.id===state.workspaceId)?.name||'Workspace')}</div><h1>Settings</h1><p>Manage your account and workspace access.</p></div></div><div class="settings-grid"><nav class="settings-nav"><button class="active" data-action="settings-account">My account</button><button data-action="settings-members">Members & invites</button><button data-action="settings-workspace">Workspace details</button></nav><section class="settings-panel"><div id="settings-panel"><h2>Profile</h2><p>Update your name and password. Your email is used to sign in.</p><form data-form="profile"><div class="field"><label>Name</label><input name="name" required maxlength="80" value="${h(state.user.name)}"></div><div class="field"><label>Email</label><input value="${h(state.user.email)}" disabled></div><div class="form-feedback"></div><button class="btn btn-primary btn-small">Save profile</button></form><div class="inspector-section">Change password</div><form data-form="password"><div class="field"><label>Current password</label><input name="currentPassword" type="password" required></div><div class="field"><label>New password</label><input name="newPassword" type="password" minlength="10" required></div><div class="form-feedback"></div><button class="btn btn-secondary btn-small">Update password</button></form><div class="inspector-section">Session</div><button class="btn btn-quiet btn-small" data-action="signout">Sign out</button></div></section></div></main>`;
  app.innerHTML=shell(content,{active:'settings',crumb:'Settings'}); state.settingsMembers=members.members; state.settingsRole=role;
}
function showSettingsMembers(){const panel=document.querySelector('#settings-panel');if(!panel)return;panel.innerHTML=`<h2>Members & invitations</h2><p>Workspace access applies to every project. Owners can manage roles and invitations.</p>${state.settingsRole==='Owner'?`<form data-form="invite" style="display:flex;gap:7px;align-items:flex-end"><div class="field" style="margin:0;flex:1"><label>Email address</label><input name="email" type="email" required placeholder="teammate@company.com"></div><div class="field" style="margin:0;width:110px"><label>Role</label><select name="role"><option>Editor</option><option>Viewer</option></select></div><button class="btn btn-primary btn-small">Invite</button></form><div class="form-feedback" id="invite-feedback" style="margin-top:9px"></div>`:''}<div class="inspector-section">Workspace members · ${state.settingsMembers.length}</div>${state.settingsMembers.map(m=>`<div class="member-row"><span class="user-avatar">${h(initials(m.name))}</span><span class="member-info"><strong>${h(m.name)} ${m.id===state.user.id?'<span class="muted">(you)</span>':''}</strong><small>${h(m.email)}</small></span>${state.settingsRole==='Owner'&&m.id!==state.user.id?`<select data-input="member-role" data-id="${m.id}" aria-label="Role for ${h(m.name)}"><option ${m.role==='Editor'?'selected':''}>Editor</option><option ${m.role==='Viewer'?'selected':''}>Viewer</option><option ${m.role==='Owner'?'selected':''}>Owner</option></select><button class="btn-icon" data-action="remove-member" data-id="${m.id}" title="Remove member">×</button>`:`<span class="tag">${h(m.role)}</span>`}</div>`).join('')}`;}
function showSettingsWorkspace(){const panel=document.querySelector('#settings-panel');if(!panel)return;const ws=state.workspaces.find(w=>w.id===state.workspaceId);panel.innerHTML=`<h2>Workspace</h2><p>Manage this workspace and create another private workspace for a different team.</p><form data-form="workspace-rename"><div class="field"><label>Workspace name</label><input name="name" required maxlength="100" value="${h(ws?.name||'')}"></div><div class="form-feedback"></div><button class="btn btn-primary btn-small" ${ws?.role==='Owner'?'':'disabled'}>Save workspace name</button></form><div class="inspector-section">Another team?</div><button class="btn btn-secondary btn-small" data-action="create-workspace">＋ Create another workspace</button><p class="field-hint" style="margin-top:10px">Workspace ownership transfer is not available in this version.</p>`;}

