const COMPONENTS=[
  {type:'client',name:'Client',icon:'◉',group:'Clients',color:'#e9f2ff'}, {type:'web',name:'Web app',icon:'▣',group:'Clients',color:'#e9f2ff'}, {type:'mobile',name:'Mobile app',icon:'▯',group:'Clients',color:'#e9f2ff'},
  {type:'api',name:'API gateway',icon:'⇄',group:'Application',color:'#e8f4ef'}, {type:'service',name:'Service',icon:'◇',group:'Application',color:'#e8f4ef'}, {type:'function',name:'Function',icon:'λ',group:'Application',color:'#e8f4ef'},
  {type:'database',name:'Database',icon:'▤',group:'Data',color:'#fff3e2'}, {type:'cache',name:'Cache',icon:'◈',group:'Data',color:'#fff3e2'}, {type:'queue',name:'Queue / topic',icon:'⇢',group:'Data',color:'#fff3e2'}, {type:'storage',name:'Object storage',icon:'▧',group:'Data',color:'#fff3e2'},
  {type:'network',name:'Network / CDN',icon:'⌁',group:'Infrastructure',color:'#f1edff'}, {type:'cloud',name:'Cloud platform',icon:'☁',group:'Infrastructure',color:'#f1edff'}, {type:'external',name:'External system',icon:'↗',group:'Infrastructure',color:'#f1edff'},
];
const SHAPES=[
  {type:'shape-rectangle',name:'Rectangle box',icon:'▭',group:'Shapes & notes',color:'#edf4ef',props:{shape:'rectangle',fill:'#f3f8f4',stroke:'#769783',textColor:'#30473c'}},
  {type:'shape-rounded',name:'Rounded box',icon:'▢',group:'Shapes & notes',color:'#edf4ef',props:{shape:'rounded',fill:'#eef5f1',stroke:'#769783',textColor:'#30473c'}},
  {type:'shape-ellipse',name:'Ellipse',icon:'⬭',group:'Shapes & notes',color:'#f0edfc',props:{shape:'ellipse',fill:'#f4f1ff',stroke:'#9587bb',textColor:'#40385b'}},
  {type:'shape-diamond',name:'Decision diamond',icon:'◇',group:'Shapes & notes',color:'#fff3e2',props:{shape:'diamond',fill:'#fff5df',stroke:'#c39952',textColor:'#604b2d'}},
  {type:'text-note',name:'Text annotation',icon:'T',group:'Shapes & notes',color:'#fff7e5',props:{fontStyle:'handwritten',fontSize:18,color:'#4d4434',background:'#fff7e5'}},
];
function componentDefinition(type,doc=state.editor?.doc){return COMPONENTS.find(c=>c.type===type)||SHAPES.find(c=>c.type===type)||doc?.customTypes?.find(c=>c.type===type)||{name:type,icon:'◇',color:'#f2edfa'};}
function defaultNode(type,x,y,name){const component=componentDefinition(type);return{id:uid(),type,name:name||component.name,description:component.description||'',x,y,w:type==='text-note'?220:158,h:type==='text-note'?90:76,icon:component.icon,layer:'layer-main',locked:false,props:clone(component.props||{}),group:''};}
function defaultDoc(){return{schemaVersion:1,nodes:[],edges:[],layers:[{id:'layer-main',name:'Main',visible:true,locked:false}],customTypes:[],viewport:{x:0,y:0,zoom:1}};}
function visibleNodes(ed=state.editor){return ed.doc.nodes.filter(n=>{const layer=ed.doc.layers.find(l=>l.id===n.layer);return !layer||layer.visible!==false;});}
