  if(draft?.doc){if(draft.baseRevision===diagram.revision){ed.doc=draft.doc;const ops=diffOps(diagram.data,draft.doc);if(ops.length){ed.pendingOps.push(...ops);ed.saveError=true;toast('Restored your unsaved local changes. Saving now.','success');scheduleSave(50);}}else{ed.conflict=true;ed.localConflictDoc=draft.doc;}}
  const nodes=ed.doc.nodes;const status=ed.conflict?'error':ed.offline?'offline':ed.saveError?'error':'saved';
  app.innerHTML=`<div class="editor-shell"><header class="editor-top"><button class="editor-back" data-action="project-back" data-id="${diagram.projectId}" title="Back to project"><span class="icon">←</span> Back</button><div class="editor-divider"></div><div class="editor-title-wrap"><input class="editor-title" data-input="diagram-title" aria-label="Diagram name" value="${h(diagram.name)}" maxlength="120"></div><span class="save-status" id="save-status"><i class="save-dot ${status==='saved'?'':status}"></i><span>${ed.conflict?'Conflict':ed.saveError?'Save error':ed.offline?'Offline':'Saved'}</span></span><div class="editor-divider"></div><div class="editor-tools"><button class="btn-icon" data-action="undo" title="Undo (Ctrl+Z)" aria-label="Undo">↶</button><button class="btn-icon" data-action="redo" title="Redo (Ctrl+Shift+Z)" aria-label="Redo">↷</button><span class="editor-divider hide-mobile"></span><button class="btn-icon hide-mobile" data-action="analyze" title="Validate diagram" aria-label="Validate">✓</button><button class="btn-icon hide-mobile" data-action="auto-layout" title="Auto layout">⌘</button><button class="btn-icon hide-tablet" data-action="versions" title="Version history">◷</button><button class="btn-icon hide-tablet" data-action="comments" title="Comments">▤</button><button class="btn-icon hide-tablet" data-action="share" title="Create view-only link">↗</button><div class="editor-divider hide-mobile"></div><button class="btn btn-secondary hide-mobile" data-action="import">Import</button><button class="btn btn-secondary" data-action="export-menu"><span class="icon">↓</span> Export</button></div></header><div class="editor-body"><aside class="palette" id="palette"><div class="panel-head"><span>Components & shapes</span><button class="btn-icon" data-action="custom-component" aria-label="Create custom component" title="Create custom component">＋</button></div><div class="palette-search"><span class="search-icon">⌕</span><input data-input="palette-search" aria-label="Search components" placeholder="Search components…"></div><div class="palette-body" id="palette-body"></div></aside><section class="canvas-wrap grid-dots" id="canvas-wrap"><div class="canvas-toolbar" role="toolbar" aria-label="Canvas tools"><button class="btn-icon active" data-tool="select" title="Select / move (V)" aria-label="Select">↖</button><button class="btn-icon" data-tool="connect" title="Connect components (C)" aria-label="Connect">↗</button><button class="btn-icon" data-tool="box" title="Draw a general box (drag)" aria-label="Draw box">▱</button><button class="btn-icon" data-tool="pen" title="Freehand pen (drag)" aria-label="Freehand pen">✎</button><button class="btn-icon" data-tool="text" title="Type directly on the canvas" aria-label="Add text">T</button><button class="btn-icon" data-tool="pan" title="Pan canvas (Space)" aria-label="Pan">✥</button><span class="editor-divider"></span><button class="btn-icon" data-action="zoom-out" title="Zoom out">−</button><button class="btn-icon" data-action="zoom-label" id="zoom-label" title="Current zoom">100%</button><button class="btn-icon" data-action="zoom-in" title="Zoom in">＋</button><button class="btn-icon" data-action="fit" title="Fit diagram to view">⤢</button><span class="editor-divider"></span><button class="btn-icon" data-action="grid-toggle" title="Toggle grid">▦</button><button class="btn-icon" data-action="navigator" title="Find a component">⌕</button></div><canvas class="diagram-canvas" id="diagram-canvas" aria-label="Architecture diagram canvas"></canvas><div class="canvas-hint" id="canvas-hint">Double-click any shape to write · choose T then click the board for text</div><div class="minimap"><canvas id="minimap"></canvas></div></section><aside class="inspector" id="inspector"><div class="panel-head"><span>Inspector</span><button class="btn-icon" data-action="clear-selection" aria-label="Clear selection">×</button></div><div id="inspector-content"></div><div class="inspector-section" style="margin:0 13px">Layers</div><div id="layers" class="layer-list"></div></aside></div><footer class="editor-bottom"><span><strong id="selection-status">${nodes.length} components</strong> · <span id="edge-status">${ed.doc.edges.length} connections</span> · ${h(ed.role)} access</span><span>Space pan · V select · C connect · P pen · T text · B box · Ctrl/⌘ Z undo</span></footer></div>`;
