  if(ed.doc.nodes.length===0)setTimeout(()=>{if(state.editor===ed&&ed.doc.nodes.length===0)toast('Start by dragging a component from the left palette onto the canvas.');},700);
  window.addEventListener('online',handleOnline);window.addEventListener('offline',handleOffline);
