function renderConflictBanner(){const bar=document.createElement('div');bar.id='conflict-banner';bar.style.cssText='position:absolute;z-index:10;top:65px;left:50%;transform:translateX(-50%);background:#fff4e6;border:1px solid #ead1a9;border-radius:9px;padding:10px 13px;font-size:10px;color:#745429;box-shadow:0 5px 20px #d9c8ae';bar.innerHTML=`Another edit was saved at revision ${state.editor.diagram.revision}. Your local work is kept on this device. <button class="text-link" data-action="download-local-draft" style="border:0;background:none">Download local draft</button> <button class="text-link" data-action="reload-remote" style="border:0;background:none">Load latest</button>`;document.querySelector('.editor-shell').append(bar);}
function renderPalette(){const ed=state.editor;if(!ed)return;const q=(ed.paletteQuery||'').toLowerCase();const components=[...COMPONENTS,...SHAPES,...(ed.doc.customTypes||[]).map(c=>({...c,group:'Custom',color:'#f2edfa'}))];const filtered=components.filter(c=>`${c.name} ${c.group} ${c.type}`.toLowerCase().includes(q));const groups=[...new Set(filtered.map(c=>c.group))];document.querySelector('#palette-body').innerHTML=groups.length?groups.map(g=>`<div class="palette-group"><div class="palette-group-title">${h(g)}</div>${filtered.filter(c=>c.group===g).map(c=>`<button class="palette-item" draggable="true" data-action="add-component" data-type="${h(c.type)}"><span class="palette-glyph">${h(c.icon)}</span>${h(c.name)}</button>`).join('')}</div>`).join(''):`<div class="inspector-empty">No matching components or shapes.</div>`;}
function renderInspector(){const ed=state.editor;const panel=document.querySelector('#inspector-content');if(!ed||!panel)return;const selectedNodes=ed.doc.nodes.filter(n=>ed.selected.has(n.id));const edge=ed.doc.edges.find(e=>e.id===ed.selectedEdge);if(edge){panel.innerHTML=`<div class="inspector-content"><div class="eyebrow">Connection</div><div class="field"><label>Label</label><input data-prop="edge.label" value="${h(edge.label||'')}" placeholder="e.g. HTTPS, reads, publishes"></div><div class="field"><label>Line style</label><select data-prop="edge.style"><option value="solid" ${edge.style!=='dashed'?'selected':''}>Solid</option><option value="dashed" ${edge.style==='dashed'?'selected':''}>Dashed</option></select></div><div class="field"><label>Direction</label><select data-prop="edge.direction"><option value="forward" ${edge.direction!=='both'?'selected':''}>Forward</option><option value="both" ${edge.direction==='both'?'selected':''}>Both directions</option><option value="none">No arrow</option></select></div><div class="field"><label>Color</label><input data-prop="edge.color" type="color" value="${h(edge.color||'#64748b')}" style="height:35px;padding:3px"></div><div class="inspector-section">Endpoints</div><div class="property-row"><span>From</span><strong>${h(ed.doc.nodes.find(n=>n.id===edge.source)?.name||'Unknown')}</strong></div><div class="property-row"><span>To</span><strong>${h(ed.doc.nodes.find(n=>n.id===edge.target)?.name||'Unknown')}</strong></div><button class="btn btn-danger btn-small" data-action="delete-selection" style="margin-top:17px;width:100%">Delete connection</button></div>`;return;}
  if(selectedNodes.length!==1){panel.innerHTML=`<div class="inspector-empty"><div class="empty-icon">${selectedNodes.length>1?'▣':'◇'}</div>${selectedNodes.length>1?`${selectedNodes.length} components selected.<br>Drag to move, group, align, duplicate, or delete.`:'Select a component or connection to edit its properties.'}${selectedNodes.length>1?`<div style="display:grid;gap:6px;margin-top:14px"><button class="btn btn-secondary btn-small" data-action="group-selection">Group selected</button><button class="btn btn-secondary btn-small" data-action="align-selection">Align vertically</button><button class="btn btn-secondary btn-small" data-action="duplicate-selection">Duplicate selection</button><button class="btn btn-danger btn-small" data-action="delete-selection">Delete selection</button></div>`:''}</div>`;return;}
  const n=selectedNodes[0],props=n.props||{};if(n.type==='text-note'){panel.innerHTML=`<div class="inspector-content"><div class="eyebrow">Text annotation</div><div class="field"><label>Text</label><textarea rows="3" readonly>${h(n.name)}</textarea><button class="btn btn-secondary btn-small" data-action="edit-text-note" style="width:100%">Edit text</button></div><div class="field"><label>Writing style</label><select data-prop="node.fontStyle" data-commit-on-change="true"><option value="handwritten" ${props.fontStyle!=='standard'?'selected':''}>Handwritten</option><option value="standard" ${props.fontStyle==='standard'?'selected':''}>Standard</option></select></div><div class="field"><label>Text color</label><input type="color" data-prop="node.color" data-commit-on-change="true" value="${safeColor(props.color||'#4d4434')}"></div><div class="field"><label>Background</label><select data-prop="node.background" data-commit-on-change="true"><option value="#fff7e5" ${props.background!=='transparent'?'selected':''}>Warm note</option><option value="transparent" ${props.background==='transparent'?'selected':''}>Transparent</option></select></div><div class="inspector-section">Position & size</div><div class="field"><label>Width</label><input type="number" data-prop="node.w" min="80" value="${Math.round(n.w)}"></div><div class="field"><label>Height</label><input type="number" data-prop="node.h" min="36" value="${Math.round(n.h)}"></div><button class="btn btn-danger btn-small" data-action="delete-selection" style="width:100%;margin-top:8px">Delete annotation</button></div>`;return;}if(n.type.startsWith('shape-')){panel.innerHTML=`<div class="inspector-content"><div class="eyebrow">Diagram shape</div><div class="field"><label>Label</label><input data-prop="node.name" data-commit-on-change="true" value="${h(n.name)}" maxlength="160"></div><div class="field"><label>Shape</label><select data-prop="node.shape" data-commit-on-change="true"><option value="rectangle" ${props.shape==='rectangle'?'selected':''}>Rectangle</option><option value="rounded" ${props.shape==='rounded'?'selected':''}>Rounded box</option><option value="ellipse" ${props.shape==='ellipse'?'selected':''}>Ellipse</option><option value="diamond" ${props.shape==='diamond'?'selected':''}>Decision diamond</option></select></div><div class="field"><label>Fill</label><input type="color" data-prop="node.fill" data-commit-on-change="true" value="${safeColor(props.fill||'#f3f8f4')}"></div><div class="field"><label>Outline</label><input type="color" data-prop="node.stroke" data-commit-on-change="true" value="${safeColor(props.stroke||'#769783')}"></div><div class="field"><label>Label color</label><input type="color" data-prop="node.textColor" data-commit-on-change="true" value="${safeColor(props.textColor||'#30473c')}"></div><div class="inspector-section">Position & size</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px"><div class="field"><label>X</label><input type="number" data-prop="node.x" value="${Math.round(n.x)}"></div><div class="field"><label>Y</label><input type="number" data-prop="node.y" value="${Math.round(n.y)}"></div><div class="field"><label>Width</label><input type="number" data-prop="node.w" min="80" value="${Math.round(n.w)}"></div><div class="field"><label>Height</label><input type="number" data-prop="node.h" min="52" value="${Math.round(n.h)}"></div></div><button class="btn btn-danger btn-small" data-action="delete-selection" style="width:100%;margin-top:8px">Delete shape</button></div>`;return;}if(n.type==='freehand'){panel.innerHTML=`<div class="inspector-content"><div class="eyebrow">Freehand stroke</div><div class="field"><label>Ink color</label><input type="color" data-prop="node.stroke" data-commit-on-change="true" value="${safeColor(props.stroke||'#2f6d53')}"></div><div class="field"><label>Stroke width</label><input type="number" data-prop="node.strokeWidth" data-commit-on-change="true" min="1" max="16" value="${Math.min(16,Math.max(1,Number(props.strokeWidth)||3))}"></div><p class="field-hint">Drag the pen tool across the canvas to add another stroke.</p><button class="btn btn-danger btn-small" data-action="delete-selection" style="width:100%;margin-top:8px">Delete stroke</button></div>`;return;}panel.innerHTML=`<div class="inspector-content"><div class="eyebrow">${h(n.type)} component</div><div class="field"><label>Name</label><input data-prop="node.name" value="${h(n.name)}" maxlength="160"></div><div class="field"><label>Description</label><textarea data-prop="node.description" rows="3" maxlength="1200" placeholder="What does this component do?">${h(n.description||'')}</textarea></div><div class="field"><label>Icon</label><input data-prop="node.icon" value="${h(n.icon||'◇')}" maxlength="4"></div><div class="field"><label>Layer</label><select data-prop="node.layer">${ed.doc.layers.map(l=>`<option value="${h(l.id)}" ${l.id===n.layer?'selected':''}>${h(l.name)}</option>`).join('')}</select></div><div class="inspector-section">Position & size</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px"><div class="field"><label>X</label><input type="number" data-prop="node.x" value="${Math.round(n.x)}"></div><div class="field"><label>Y</label><input type="number" data-prop="node.y" value="${Math.round(n.y)}"></div><div class="field"><label>Width</label><input type="number" data-prop="node.w" min="36" value="${Math.round(n.w)}"></div><div class="field"><label>Height</label><input type="number" data-prop="node.h" min="28" value="${Math.round(n.h)}"></div></div><div class="property-row"><span>Lock position</span><input type="checkbox" data-prop="node.locked" ${n.locked?'checked':''} aria-label="Lock position"></div><div class="field"><label>Group</label><input data-prop="node.group" value="${h(n.group||'')}" placeholder="e.g. Private subnet"></div><div class="inspector-section">Properties (JSON)</div><div class="field"><textarea data-prop="node.props" rows="5" aria-label="Component properties">${h(JSON.stringify(n.props||{},null,2))}</textarea><span class="field-hint">Use a JSON object for custom fields like region or tier.</span></div><button class="btn btn-secondary btn-small" data-action="duplicate-selection" style="width:100%;margin-top:3px">Duplicate component</button><button class="btn btn-danger btn-small" data-action="delete-selection" style="width:100%;margin-top:7px">Delete component</button></div>`;}
function renderLayers(){const ed=state.editor;const layerBox=document.querySelector('#layers');if(!ed||!layerBox)return;layerBox.innerHTML=ed.doc.layers.map((l,i)=>`<div class="layer-row"><span style="color:#9aaa9f">${l.locked?'▣':'≡'}</span><span>${h(l.name)}</span><div class="layer-actions"><button data-action="layer-visible" data-id="${l.id}" title="${l.visible===false?'Show':'Hide'} layer">${l.visible===false?'◌':'◉'}</button><button data-action="layer-lock" data-id="${l.id}" title="${l.locked?'Unlock':'Lock'} layer">${l.locked?'▣':'⌑'}</button><button data-action="layer-move" data-id="${l.id}" data-dir="-1" title="Move layer up" ${i===0?'disabled':''}>↑</button><button data-action="layer-move" data-id="${l.id}" data-dir="1" title="Move layer down" ${i===ed.doc.layers.length-1?'disabled':''}>↓</button></div></div>`).join('')+`<button class="btn btn-quiet btn-small" data-action="add-layer" style="width:100%;margin-top:5px">＋ Add layer</button>`;}

function bindCanvas(){const canvas=document.querySelector('#diagram-canvas');if(!canvas)return;const host=document.createElement('div');host.id='inline-editor-host';host.className='inline-editor-host';canvas.parentElement.append(host);canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',canvasDown);canvas.addEventListener('pointermove',canvasMove);canvas.addEventListener('pointerup',canvasUp);canvas.addEventListener('pointercancel',canvasUp);canvas.addEventListener('dblclick',e=>{const ed=state.editor;if(!ed||ed.readOnly)return;const p=screenToWorld(e.clientX,e.clientY),node=findNode(p.x,p.y);startInlineTextEditor(p,node&&node.type!=='freehand'?node.id:'');});canvas.addEventListener('wheel',canvasWheel,{passive:false});canvas.addEventListener('dragover',e=>e.preventDefault());canvas.addEventListener('drop',e=>{e.preventDefault();const type=e.dataTransfer.getData('text/plain');if(type){const p=screenToWorld(e.clientX,e.clientY);addNode(type,p.x-79,p.y-38);}});new ResizeObserver(()=>drawCanvas()).observe(canvas);document.querySelectorAll('.palette-item').forEach(item=>item.addEventListener('dragstart',e=>e.dataTransfer.setData('text/plain',item.dataset.type)));}
function canvasSize(){const c=document.querySelector('#diagram-canvas');if(!c)return;const r=c.getBoundingClientRect(),dpr=Math.max(1,window.devicePixelRatio||1);if(c.width!==Math.round(r.width*dpr)||c.height!==Math.round(r.height*dpr)){c.width=Math.round(r.width*dpr);c.height=Math.round(r.height*dpr);}return{width:r.width,height:r.height,dpr};}
function roundedRect(ctx,x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);}
function wrapCanvasText(ctx,text,maxWidth){const lines=[];for(const paragraph of String(text||'').split('\n')){const words=paragraph.split(/\s+/).filter(Boolean);if(!words.length){lines.push('');continue;}let line='';for(const word of words){const next=line?`${line} ${word}`:word;if(line&&ctx.measureText(next).width>maxWidth){lines.push(line);line=word;}else line=next;}lines.push(line);}return lines;}
function drawLabelBlock(ctx,text,x,y,w,h,fontSize=13,fontStyle='standard',color='#30473c',align='center'){const family=fontStyle==='handwritten'? '"Segoe Print","Comic Sans MS",cursive':'Inter,system-ui,sans-serif';ctx.font=`${fontStyle==='handwritten'?'italic ':''}${fontSize}px ${family}`;const lines=wrapCanvasText(ctx,text,Math.max(30,w-24)),lineHeight=fontSize*1.35,maxLines=Math.max(1,Math.floor((h-14)/lineHeight)),shown=lines.slice(0,maxLines);if(lines.length>maxLines&&shown.length)shown[shown.length-1]=shown.at(-1).replace(/.{0,2}$/,'…');ctx.fillStyle=safeColor(color);ctx.textAlign=align;ctx.textBaseline='middle';const startY=y+h/2-(shown.length-1)*lineHeight/2;shown.forEach((line,i)=>ctx.fillText(line,align==='center'?x+w/2:x+12,startY+i*lineHeight));ctx.textAlign='left';ctx.textBaseline='alphabetic';}
function drawStroke(ctx,points,x,y,color,width){if(!Array.isArray(points)||!points.length)return;ctx.save();ctx.strokeStyle=safeColor(color);ctx.lineWidth=Math.max(1,Math.min(16,Number(width)||3));ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(x+(points[0].x||0),y+(points[0].y||0));for(let i=1;i<points.length;i++)ctx.lineTo(x+(points[i].x||0),y+(points[i].y||0));ctx.stroke();ctx.restore();}
function drawSpecialNode(ctx,n,selected,isEditing=false){const props=n.props||{};if(n.type==='freehand'){drawStroke(ctx,props.points,n.x,n.y,props.stroke,props.strokeWidth);if(selected){ctx.save();ctx.strokeStyle='#338060';ctx.lineWidth=1.5;ctx.setLineDash([4,3]);ctx.strokeRect(n.x,n.y,n.w,n.h);ctx.setLineDash([]);ctx.fillStyle='#32815e';ctx.fillRect(n.x+n.w-4,n.y+n.h-4,8,8);ctx.restore();}return true;}if(n.type==='text-note'){ctx.save();if(props.background&&props.background!=='transparent'){ctx.fillStyle=safeColor(props.background);roundedRect(ctx,n.x,n.y,n.w,n.h,8);ctx.fill();}if(selected){ctx.strokeStyle='#338060';ctx.lineWidth=1.5;ctx.setLineDash([4,3]);roundedRect(ctx,n.x,n.y,n.w,n.h,7);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#32815e';ctx.fillRect(n.x+n.w-4,n.y+n.h-4,8,8);}const fontSize=Math.max(12,Math.min(36,Number(props.fontSize)||18)),family=props.fontStyle==='handwritten'?'"Segoe Print","Comic Sans MS",cursive':'Inter,system-ui,sans-serif';ctx.font=`${props.fontStyle==='handwritten'?'italic ':''}${fontSize}px ${family}`;const lines=wrapCanvasText(ctx,n.name,Math.max(30,n.w-24)),lineHeight=fontSize*1.3,maxLines=Math.max(1,Math.floor((n.h-18)/lineHeight));ctx.fillStyle=safeColor(props.color||'#4d4434');ctx.textAlign='left';ctx.textBaseline='top';if(!isEditing)lines.slice(0,maxLines).forEach((line,i)=>ctx.fillText(line,n.x+12,n.y+10+i*lineHeight));ctx.restore();return true;}if(n.type.startsWith('shape-')){const shape=props.shape||n.type.slice(6);ctx.save();ctx.fillStyle=safeColor(props.fill||'#f3f8f4');ctx.strokeStyle=selected?'#338060':safeColor(props.stroke||'#769783');ctx.lineWidth=selected?2.2:1.5;ctx.beginPath();if(shape==='ellipse')ctx.ellipse(n.x+n.w/2,n.y+n.h/2,n.w/2,n.h/2,0,0,Math.PI*2);else if(shape==='diamond'){ctx.moveTo(n.x+n.w/2,n.y);ctx.lineTo(n.x+n.w,n.y+n.h/2);ctx.lineTo(n.x+n.w/2,n.y+n.h);ctx.lineTo(n.x,n.y+n.h/2);ctx.closePath();}else ctx.roundRect(n.x,n.y,n.w,n.h,shape==='rounded'?14:2);ctx.fill();ctx.stroke();const shapeLabel=['Box','Rectangle box','Rounded box','Ellipse','Decision diamond'].includes(n.name)?'':n.name;if(!isEditing&&shapeLabel)drawLabelBlock(ctx,shapeLabel,n.x,n.y,n.w,n.h,Math.min(17,Math.max(11,Number(props.fontSize)||13)),props.fontStyle||'standard',props.textColor||'#30473c');if(selected){ctx.fillStyle='#32815e';ctx.fillRect(n.x+n.w-4,n.y+n.h-4,8,8);}ctx.restore();return true;}return false;}
function wrapPlainText(text,maxChars){const out=[];for(const paragraph of String(text||'').split('\n')){let line='';for(const word of paragraph.split(/\s+/).filter(Boolean)){const next=line?`${line} ${word}`:word;if(line&&next.length>maxChars){out.push(line);line=word;}else line=next;}out.push(line);}return out;}
function worldBounds(nodes=state.editor?.doc.nodes||[]){if(!nodes.length)return{minX:-200,minY:-130,maxX:300,maxY:240};return{minX:Math.min(...nodes.map(n=>n.x))-80,minY:Math.min(...nodes.map(n=>n.y))-70,maxX:Math.max(...nodes.map(n=>n.x+n.w))+80,maxY:Math.max(...nodes.map(n=>n.y+n.h))+70};}
function drawCanvas(){const ed=state.editor;const canvas=document.querySelector('#diagram-canvas');if(!ed||!canvas)return;const size=canvasSize();if(!size)return;const ctx=canvas.getContext('2d');ctx.setTransform(size.dpr,0,0,size.dpr,0,0);ctx.clearRect(0,0,size.width,size.height);ctx.setTransform(size.dpr*ed.camera.zoom,0,0,size.dpr*ed.camera.zoom,size.dpr*ed.camera.x,size.dpr*ed.camera.y);const visible=visibleNodes(ed);const nodeById=new Map(ed.doc.nodes.map(n=>[n.id,n]));const screenBox={x:-ed.camera.x/ed.camera.zoom-200,y:-ed.camera.y/ed.camera.zoom-200,w:size.width/ed.camera.zoom+400,h:size.height/ed.camera.zoom+400};
  for(const group of new Set(visible.filter(n=>n.group).map(n=>n.group))){const ns=visible.filter(n=>n.group===group);if(ns.length<2)continue;const x=Math.min(...ns.map(n=>n.x))-15,y=Math.min(...ns.map(n=>n.y))-29,w=Math.max(...ns.map(n=>n.x+n.w))-x+15,h=Math.max(...ns.map(n=>n.y+n.h))-y+14;ctx.fillStyle='rgba(232,243,237,.42)';ctx.strokeStyle='#b4cdbd';ctx.lineWidth=1.2;ctx.setLineDash([5,4]);roundedRect(ctx,x,y,w,h,11);ctx.fill();ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#59806c';ctx.font='600 10px Inter,system-ui';ctx.fillText(group,x+10,y+17);}
  for(const edge of ed.doc.edges){const a=nodeById.get(edge.source),b=nodeById.get(edge.target);if(!a||!b)continue;const la=ed.doc.layers.find(l=>l.id===a.layer),lb=ed.doc.layers.find(l=>l.id===b.layer);if(la?.visible===false||lb?.visible===false)continue;const sx=a.x+a.w/2,sy=a.y+a.h/2,tx=b.x+b.w/2,ty=b.y+b.h/2;if(Math.max(sx,tx)<screenBox.x||Math.min(sx,tx)>screenBox.x+screenBox.w||Math.max(sy,ty)<screenBox.y||Math.min(sy,ty)>screenBox.y+screenBox.h)continue;const selected=ed.selectedEdge===edge.id;ctx.strokeStyle=selected?'#2f8562':edge.color||'#71847a';ctx.fillStyle=ctx.strokeStyle;ctx.lineWidth=selected?2.5:1.6;ctx.setLineDash(edge.style==='dashed'?[6,5]:[]);ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(tx,ty);ctx.stroke();ctx.setLineDash([]);if(edge.direction!=='none'){drawArrow(ctx,sx,sy,tx,ty);if(edge.direction==='both')drawArrow(ctx,tx,ty,sx,sy);}if(edge.label){const mx=(sx+tx)/2,my=(sy+ty)/2;ctx.font='10px Inter,system-ui';const tw=ctx.measureText(edge.label).width;ctx.fillStyle='rgba(255,255,255,.96)';roundedRect(ctx,mx-tw/2-5,my-8,tw+10,16,4);ctx.fill();ctx.fillStyle='#556a60';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(edge.label,mx,my);ctx.textAlign='start';ctx.textBaseline='alphabetic';}}
  for(const n of visible){if(n.x+n.w<screenBox.x||n.x>screenBox.x+screenBox.w||n.y+n.h<screenBox.y||n.y>screenBox.y+screenBox.h)continue;const selected=ed.selected.has(n.id),editing=ed.inlineEditor?.nodeId===n.id;if(drawSpecialNode(ctx,n,selected,editing))continue;const c=COMPONENTS.find(x=>x.type===n.type);ctx.save();ctx.shadowColor='rgba(26,57,43,.08)';ctx.shadowBlur=selected?0:8;ctx.shadowOffsetY=selected?0:3;ctx.fillStyle='#fff';ctx.strokeStyle=selected?'#338060':'#cbdad1';ctx.lineWidth=selected?2:1;roundedRect(ctx,n.x,n.y,n.w,n.h,9);ctx.fill();ctx.stroke();ctx.shadowColor='transparent';const baseColor=c?.color||'#e9f2ed';ctx.fillStyle=baseColor;roundedRect(ctx,n.x+10,n.y+10,27,27,7);ctx.fill();ctx.fillStyle='#35745a';ctx.font='14px Inter,system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(n.icon||c?.icon||'◇',n.x+23.5,n.y+23.5);ctx.textAlign='left';ctx.fillStyle='#30473c';ctx.font='650 11px Inter,system-ui';ctx.textBaseline='middle';if(!editing){const name=String(n.name||'Untitled');ctx.fillText(name.length>24?name.slice(0,23)+'…':name,n.x+46,n.y+22);}ctx.fillStyle='#87968e';ctx.font='9px Inter,system-ui';ctx.fillText(String(n.type||'component').replace(/\b\w/g,x=>x.toUpperCase()),n.x+46,n.y+43);if(n.description){ctx.fillStyle='#718178';ctx.font='9px Inter,system-ui';const desc=n.description.length>28?n.description.slice(0,26)+'…':n.description;ctx.fillText(desc,n.x+10,n.y+n.h-11);}if(n.locked){ctx.fillStyle='#87968e';ctx.font='10px Inter,system-ui';ctx.fillText('▣',n.x+n.w-18,n.y+16);}const commentCount=ed.comments.filter(c=>c.anchor?.nodeId===n.id).length;if(commentCount){ctx.fillStyle='#d28d38';ctx.beginPath();ctx.arc(n.x+n.w-7,n.y+5,8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.font='bold 8px Inter,system-ui';ctx.textAlign='center';ctx.fillText(String(commentCount),n.x+n.w-7,n.y+5);ctx.textAlign='left';}if(selected){ctx.fillStyle='#32815e';ctx.fillRect(n.x+n.w-4,n.y+n.h-4,8,8);}ctx.restore();}
  if(ed.drag?.kind==='draw-box'){const q=ed.drag,x=Math.min(q.start.x,q.end.x),y=Math.min(q.start.y,q.end.y),w=Math.abs(q.end.x-q.start.x),h=Math.abs(q.end.y-q.start.y);ctx.save();ctx.fillStyle='rgba(97,139,113,.08)';ctx.strokeStyle='#338060';ctx.lineWidth=1.5;ctx.setLineDash([6,4]);ctx.fillRect(x,y,w,h);ctx.strokeRect(x,y,w,h);ctx.restore();}if(ed.drag?.kind==='draw-ink'){const pts=ed.drag.points;if(pts.length>1){ctx.save();ctx.strokeStyle=ed.drag.stroke;ctx.lineWidth=ed.drag.strokeWidth;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(pts[0].x,pts[0].y);for(let i=1;i<pts.length;i++)ctx.lineTo(pts[i].x,pts[i].y);ctx.stroke();ctx.restore();}}
  if(ed.tool==='connect'&&ed.connectFrom){const n=ed.doc.nodes.find(x=>x.id===ed.connectFrom);if(n&&ed.pointerWorld){ctx.strokeStyle='#378462';ctx.lineWidth=1.5;ctx.setLineDash([5,4]);ctx.beginPath();ctx.moveTo(n.x+n.w/2,n.y+n.h/2);ctx.lineTo(ed.pointerWorld.x,ed.pointerWorld.y);ctx.stroke();ctx.setLineDash([]);}}
  drawMinimap(nodeById);updatePointMarkers();updateSelectionText();syncInlineTextEditor();}
function updatePointMarkers(){const ed=state.editor,box=document.querySelector('#comment-points');if(!ed||!box)return;box.innerHTML=ed.comments.filter(c=>c.anchor?.type==='point').map((c,i)=>{const left=ed.camera.x+(Number(c.anchor.x)||0)*ed.camera.zoom,top=ed.camera.y+(Number(c.anchor.y)||0)*ed.camera.zoom;return `<span title="${h(c.body)}" style="position:absolute;left:${left-9}px;top:${top-9}px;width:18px;height:18px;border-radius:50%;background:#d28d38;border:2px solid #fff;color:#fff;display:grid;place-items:center;font:bold 8px system-ui;box-shadow:0 2px 6px #809287">${(i+1)%10}</span>`;}).join('');}
function drawArrow(ctx,sx,sy,tx,ty){const angle=Math.atan2(ty-sy,tx-sx);const len=8;const x=tx-Math.cos(angle)*15,y=ty-Math.sin(angle)*15;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-len*Math.cos(angle-.42),y-len*Math.sin(angle-.42));ctx.lineTo(x-len*Math.cos(angle+.42),y-len*Math.sin(angle+.42));ctx.closePath();ctx.fill();}
function drawMinimap(nodeById){const ed=state.editor,c=document.querySelector('#minimap');if(!ed||!c)return;nodeById ||= new Map(ed.doc.nodes.map(n=>[n.id,n]));const r=c.getBoundingClientRect(),dpr=window.devicePixelRatio||1;c.width=Math.round(r.width*dpr);c.height=Math.round(r.height*dpr);const ctx=c.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,r.width,r.height);const nodes=visibleNodes(ed),b=worldBounds(nodes);const scale=Math.min((r.width-18)/(b.maxX-b.minX),(r.height-18)/(b.maxY-b.minY));const ox=(r.width-(b.maxX-b.minX)*scale)/2,oy=(r.height-(b.maxY-b.minY)*scale)/2;for(const e of ed.doc.edges){const a=nodeById.get(e.source),t=nodeById.get(e.target);if(!a||!t)continue;ctx.strokeStyle='#b1c0b7';ctx.lineWidth=.7;ctx.beginPath();ctx.moveTo(ox+(a.x+a.w/2-b.minX)*scale,oy+(a.y+a.h/2-b.minY)*scale);ctx.lineTo(ox+(t.x+t.w/2-b.minX)*scale,oy+(t.y+t.h/2-b.minY)*scale);ctx.stroke();}for(const n of nodes){ctx.fillStyle=ed.selected.has(n.id)?'#34835f':'#7fa590';ctx.fillRect(ox+(n.x-b.minX)*scale,oy+(n.y-b.minY)*scale,Math.max(2,n.w*scale),Math.max(2,n.h*scale));}const canvas=document.querySelector('#diagram-canvas'),cr=canvas.getBoundingClientRect();ctx.strokeStyle='#2a7858';ctx.lineWidth=1;ctx.strokeRect(ox+(-ed.camera.x/ed.camera.zoom-b.minX)*scale,oy+(-ed.camera.y/ed.camera.zoom-b.minY)*scale,cr.width/ed.camera.zoom*scale,cr.height/ed.camera.zoom*scale);}
function screenToWorld(clientX,clientY){const ed=state.editor,r=document.querySelector('#diagram-canvas').getBoundingClientRect();return{x:(clientX-r.left-ed.camera.x)/ed.camera.zoom,y:(clientY-r.top-ed.camera.y)/ed.camera.zoom};}
function findNode(x,y){const ed=state.editor;return visibleNodes(ed).slice().reverse().find(n=>x>=n.x&&x<=n.x+n.w&&y>=n.y&&y<=n.y+n.h);}
function pointLineDistance(px,py,x1,y1,x2,y2){const l=((px-x1)**2+(py-y1)**2)**.5;if(!l)return Math.hypot(px-x1,py-y1);const t=Math.max(0,Math.min(1,((px-x1)*(x2-x1)+(py-y1)*(y2-y1))/(l*l)));return Math.hypot(px-(x1+t*(x2-x1)),py-(y1+t*(y2-y1)));}
