function canvasDown(e){const ed=state.editor;if(ed.readOnly)return;const canvas=e.currentTarget;canvas.setPointerCapture(e.pointerId);const p=screenToWorld(e.clientX,e.clientY);if(ed.tool==='pan'||e.button===1||ed.spaceDown){ed.drag={kind:'pan',clientX:e.clientX,clientY:e.clientY,panX:ed.camera.x,panY:ed.camera.y};return;}if(e.button>0)return;if(ed.tool==='text'){e.preventDefault();const target=findNode(p.x,p.y);startInlineTextEditor(p,target&&target.type!=='freehand'?target.id:'');return;}if(ed.tool==='box'){ed.drag={kind:'draw-box',start:p,end:p};drawCanvas();return;}if(ed.tool==='pen'){ed.drag={kind:'draw-ink',points:[p],stroke:'#2f6d53',strokeWidth:3};drawCanvas();return;}if(ed.tool==='comment'){createCommentAt(p);return;}const node=findNode(p.x,p.y);if(ed.tool==='connect'){if(node){if(!ed.connectFrom){ed.connectFrom=node.id;ed.pointerWorld=p;toast(`Choose a destination for ${node.name}.`);}else if(ed.connectFrom!==node.id){addEdge(ed.connectFrom,node.id);ed.connectFrom=null;setTool('select');}else ed.connectFrom=null;}else{ed.connectFrom=null;}drawCanvas();return;}if(node){ed.selectedEdge=null;if(e.shiftKey){if(ed.selected.has(node.id))ed.selected.delete(node.id);else ed.selected.add(node.id);}else if(!ed.selected.has(node.id))ed.selected=new Set([node.id]);renderInspector();drawCanvas();const canMove=!node.locked&&!ed.doc.layers.find(l=>l.id===node.layer)?.locked;const resize=ed.selected.size===1&&p.x>node.x+node.w-12&&p.y>node.y+node.h-12;if(resize&&canMove)ed.drag={kind:'resize',nodeId:node.id,start:p,before:clone(ed.doc),w:node.w,h:node.h};else if(canMove&&ed.selected.has(node.id)){const starts={};for(const n of ed.doc.nodes)if(ed.selected.has(n.id))starts[n.id]={x:n.x,y:n.y};ed.drag={kind:'move',start:p,starts,before:clone(ed.doc)};}}else{const edge=findEdge(p.x,p.y);if(edge){ed.selected.clear();ed.selectedEdge=edge.id;renderInspector();drawCanvas();}else{ed.selected.clear();ed.selectedEdge=null;renderInspector();drawCanvas();}}}
function canvasMove(e){const ed=state.editor;if(!ed)return;const p=screenToWorld(e.clientX,e.clientY);ed.pointerWorld=p;if(!ed.drag){if(ed.tool==='connect')drawCanvas();return;}if(ed.drag.kind==='pan'){ed.camera.x=ed.drag.panX+(e.clientX-ed.drag.clientX);ed.camera.y=ed.drag.panY+(e.clientY-ed.drag.clientY);}else if(ed.drag.kind==='move'){const dx=p.x-ed.drag.start.x,dy=p.y-ed.drag.start.y;for(const n of ed.doc.nodes)if(ed.drag.starts[n.id]){n.x=ed.drag.starts[n.id].x+dx;n.y=ed.drag.starts[n.id].y+dy;}}else if(ed.drag.kind==='resize'){const n=ed.doc.nodes.find(n=>n.id===ed.drag.nodeId);if(n){n.w=Math.max(96,ed.drag.w+(p.x-ed.drag.start.x));n.h=Math.max(52,ed.drag.h+(p.y-ed.drag.start.y));}}else if(ed.drag.kind==='marquee'){ed.drag.end=p;}else if(ed.drag.kind==='draw-box'){ed.drag.end=p;}else if(ed.drag.kind==='draw-ink'){const points=ed.drag.points,last=points.at(-1);if(Math.hypot(p.x-last.x,p.y-last.y)>=2/ed.camera.zoom)points.push(p);}drawCanvas();}
function createBoxFromDrag(drag){const ed=state.editor;let x=Math.min(drag.start.x,drag.end.x),y=Math.min(drag.start.y,drag.end.y),w=Math.abs(drag.end.x-drag.start.x),h=Math.abs(drag.end.y-drag.start.y);if(w<18||h<18){toast('Drag at least 18 pixels in both directions to draw a box.');return;}if(ed.snap){x=Math.round(x/20)*20;y=Math.round(y/20)*20;w=Math.max(80,Math.round(w/20)*20);h=Math.max(52,Math.round(h/20)*20);}const node=defaultNode('shape-rectangle',x,y);node.name='';node.w=Math.max(80,w);node.h=Math.max(52,h);node.layer=ed.doc.layers[0]?.id||'layer-main';const before=clone(ed.doc);ed.doc.nodes.push(node);ed.selected=new Set([node.id]);ed.selectedEdge=null;commitChanged(before);}
function createInkFromDrag(drag){const ed=state.editor,points=drag.points;if(points.length<2){toast('Draw a longer stroke to add it to the diagram.');return;}let minX=Math.min(...points.map(p=>p.x)),minY=Math.min(...points.map(p=>p.y)),maxX=Math.max(...points.map(p=>p.x)),maxY=Math.max(...points.map(p=>p.y));const pad=8;minX-=pad;minY-=pad;maxX+=pad;maxY+=pad;const node={id:uid(),type:'freehand',name:'Pen stroke',description:'',x:minX,y:minY,w:Math.max(36,maxX-minX),h:Math.max(28,maxY-minY),icon:'✎',layer:ed.doc.layers[0]?.id||'layer-main',locked:false,group:'',props:{stroke:drag.stroke,strokeWidth:drag.strokeWidth,points:points.map(p=>({x:p.x-minX,y:p.y-minY}))}};const before=clone(ed.doc);ed.doc.nodes.push(node);ed.selected=new Set([node.id]);ed.selectedEdge=null;commitChanged(before);}
function canvasUp(e){const ed=state.editor;if(!ed||!ed.drag)return;const drag=ed.drag;ed.drag=null;if(drag.kind==='move'||drag.kind==='resize'){if(ed.snap){for(const n of ed.doc.nodes)if(ed.selected.has(n.id)){n.x=Math.round(n.x/20)*20;n.y=Math.round(n.y/20)*20;}}commitChanged(drag.before);}else if(drag.kind==='marquee'){const x1=Math.min(drag.start.x,drag.end.x),x2=Math.max(drag.start.x,drag.end.x),y1=Math.min(drag.start.y,drag.end.y),y2=Math.max(drag.start.y,drag.end.y);const found=visibleNodes(ed).filter(n=>n.x+n.w>=x1&&n.x<=x2&&n.y+n.h>=y1&&n.y<=y2);ed.selected=new Set(found.map(n=>n.id));renderInspector();}else if(drag.kind==='draw-box')createBoxFromDrag(drag);else if(drag.kind==='draw-ink')createInkFromDrag(drag);drawCanvas();}
function canvasWheel(e){e.preventDefault();const ed=state.editor;const before=screenToWorld(e.clientX,e.clientY);const factor=e.deltaY<0?1.1:.9;ed.camera.zoom=Math.max(.2,Math.min(2.5,ed.camera.zoom*factor));const r=e.currentTarget.getBoundingClientRect();ed.camera.x=e.clientX-r.left-before.x*ed.camera.zoom;ed.camera.y=e.clientY-r.top-before.y*ed.camera.zoom;refreshEditorChrome();drawCanvas();}
function setTool(tool){const ed=state.editor;if(!ed)return;ed.tool=tool;ed.connectFrom=null;document.querySelectorAll('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));document.querySelector('#diagram-canvas').style.cursor=tool==='pan'?'grab':tool==='connect'?'crosshair':tool==='text'?'text':tool==='pen'?'crosshair':tool==='box'?'crosshair':tool==='comment'?'copy':'default';const hints={connect:'Select a source component, then choose its destination.',comment:'Click a component or location to attach a comment.',pen:'Drag with a mouse, pen, or stylus to draw a freehand stroke.',box:'Drag to draw an empty box; double-click it later to write inside.',text:'Click the board to type directly; double-click any shape to edit its text.'};document.querySelector('#canvas-hint').textContent=hints[tool]||'Drag to move · Shift-click to select multiple · C to connect · Scroll to zoom';}
function refreshEditorChrome(){const ed=state.editor;if(!ed)return;const z=document.querySelector('#zoom-label');if(z)z.textContent=`${Math.round(ed.camera.zoom*100)}%`;const status=document.querySelector('#save-status');if(status){const label=ed.conflict?'Conflict':ed.offline?'Offline':ed.saving?'Saving…':ed.saveError?'Retrying save…':'Saved';status.innerHTML=`<i class="save-dot ${ed.conflict||ed.saveError?'error':ed.offline?'offline':ed.saving?'saving':''}"></i><span>${label}</span>`;}updateSelectionText();}
function updateSelectionText(){const ed=state.editor;if(!ed)return;const select=document.querySelector('#selection-status'),edge=document.querySelector('#edge-status');if(select)select.textContent=`${ed.selected.size||ed.doc.nodes.length} ${ed.selected.size===1?'selected':ed.selected.size?'selected':'components'}`;if(edge)edge.textContent=`${ed.doc.edges.length} connections`;}

function diffOps(oldDoc,newDoc){const ops=[];const oldNodes=new Map(oldDoc.nodes.map(n=>[n.id,n])),newNodes=new Map(newDoc.nodes.map(n=>[n.id,n]));for(const id of oldNodes.keys())if(!newNodes.has(id))ops.push({type:'removeNode',id});for(const [id,node]of newNodes)if(!oldNodes.has(id)||JSON.stringify(oldNodes.get(id))!==JSON.stringify(node))ops.push({type:'upsertNode',node});const oldEdges=new Map(oldDoc.edges.map(e=>[e.id,e])),newEdges=new Map(newDoc.edges.map(e=>[e.id,e]));for(const id of oldEdges.keys())if(!newEdges.has(id))ops.push({type:'removeEdge',id});for(const [id,edge]of newEdges)if(!oldEdges.has(id)||JSON.stringify(oldEdges.get(id))!==JSON.stringify(edge))ops.push({type:'upsertEdge',edge});if(JSON.stringify(oldDoc.layers)!==JSON.stringify(newDoc.layers))ops.push({type:'setLayers',layers:newDoc.layers});if(JSON.stringify(oldDoc.customTypes||[])!==JSON.stringify(newDoc.customTypes||[]))ops.push({type:'setCustomTypes',customTypes:newDoc.customTypes||[]});return ops;}
function performEdit(mutator){const ed=state.editor;if(!ed||ed.readOnly||ed.conflict)return;const before=clone(ed.doc);mutator(ed.doc);commitChanged(before);}
function commitChanged(before){const ed=state.editor;const ops=diffOps(before,ed.doc);if(!ops.length)return;if(Date.now()-ed.lastHistoryAt>600){ed.undoStack.push(before);if(ed.undoStack.length>100)ed.undoStack.shift();ed.lastHistoryAt=Date.now();}ed.redoStack=[];enqueueOps(ops);drawCanvas();renderInspector();renderLayers();}
function scheduleSave(delay=700){const ed=state.editor;if(!ed)return;clearTimeout(ed.saveTimer);ed.saveTimer=setTimeout(savePending,delay);}
async function savePending(){const ed=state.editor;if(!ed||ed.requesting||ed.conflict||!ed.pendingOps.length)return;const batch=ed.pendingOps.splice(0,1000);ed.requesting=true;ed.saving=true;refreshEditorChrome();try{const result=await api(`/api/diagrams/${ed.diagramId}/ops`,{method:'POST',body:{baseRevision:ed.baseRevision,operations:batch}});ed.baseRevision=result.revision;ed.diagram.revision=result.revision;ed.diagram.updatedAt=result.updatedAt;ed.saving=false;ed.saveError=false;ed.offline=false;if(ed.pendingOps.length){try{localStorage.setItem(ed.draftKey,JSON.stringify({baseRevision:ed.baseRevision,doc:ed.doc,at:Date.now()}));}catch{}scheduleSave(300);}else{localStorage.removeItem(ed.draftKey);toast('All changes saved','success');}refreshEditorChrome();}catch(error){ed.pendingOps=[...batch,...ed.pendingOps];ed.saving=false;if(error.status===409){ed.conflict=true;ed.saveError=true;const remote=error.payload?.diagram;if(remote){ed.remoteDiagram=remote;}renderConflictBanner();toast('A newer edit exists on the server. Your local changes are still saved on this device.','error');}else{ed.offline=!navigator.onLine;ed.saveError=true;try{localStorage.setItem(ed.draftKey,JSON.stringify({baseRevision:ed.baseRevision,doc:ed.doc,at:Date.now()}));}catch{}refreshEditorChrome();if(navigator.onLine)setTimeout(()=>{if(state.editor===ed)savePending();},4000);else toast('You are offline. Changes are stored on this device and will retry when you reconnect.','error');}}finally{ed.requesting=false;}}
function handleOnline(){const ed=state.editor;if(!ed)return;ed.offline=false;if(ed.pendingOps.length&&!ed.conflict)scheduleSave(100);refreshEditorChrome();toast('Connection restored. Syncing your changes…','success');}
function handleOffline(){if(!state.editor)return;state.editor.offline=true;refreshEditorChrome();toast('Connection lost. Your changes are being kept on this device.','error');}
function undo(){const ed=state.editor;if(!ed||!ed.undoStack.length)return;const before=ed.undoStack.pop();ed.redoStack.push(clone(ed.doc));const old=clone(ed.doc);ed.doc=before;ed.lastHistoryAt=0;enqueueOps(diffOps(old,ed.doc));renderInspector();renderLayers();drawCanvas();}
function redo(){const ed=state.editor;if(!ed||!ed.redoStack.length)return;const next=ed.redoStack.pop();ed.undoStack.push(clone(ed.doc));const old=clone(ed.doc);ed.doc=next;ed.lastHistoryAt=0;enqueueOps(diffOps(old,ed.doc));renderInspector();renderLayers();drawCanvas();}
function addNode(type,x=null,y=null,name){const ed=state.editor;if(!ed||ed.readOnly)return;const rect=document.querySelector('#diagram-canvas').getBoundingClientRect();const p=x===null?screenToWorld(rect.left+rect.width/2,rect.top+rect.height/2):{x,y};const point={x:ed.snap?Math.round(p.x/20)*20:p.x,y:ed.snap?Math.round(p.y/20)*20:p.y};if(type==='text-note'){startInlineTextEditor(point);return;}const node=defaultNode(type,point.x,point.y,name);node.layer=ed.doc.layers[0]?.id||'layer-main';if(type.startsWith('shape-')){node.name='';node.w=type==='shape-diamond'?190:180;node.h=type==='shape-diamond'?112:100;}performEdit(doc=>doc.nodes.push(node));ed.selected=new Set([node.id]);renderInspector();document.querySelector('#palette').classList.remove('open');}
function startInlineTextEditor(point={x:0,y:0},nodeId=''){const ed=state.editor;if(!ed||ed.readOnly)return;if(ed.inlineEditor)finishInlineTextEditor(true);let node=nodeId?ed.doc.nodes.find(n=>n.id===nodeId):null;if(node?.type==='freehand')node=null;if(node&&(node.locked||ed.doc.layers.find(l=>l.id===node.layer)?.locked)){toast('Unlock this layer or component before editing its text.','error');return;}const before=clone(ed.doc),previousSelection=[...ed.selected],isNew=!node;if(node&&node.type.startsWith('shape-')&&['Box','Rectangle box','Rounded box','Ellipse','Decision diamond'].includes(node.name))node.name='';if(!node){const x=ed.snap?Math.round((Number(point.x)||0)/20)*20:(Number(point.x)||0),y=ed.snap?Math.round((Number(point.y)||0)/20)*20:(Number(point.y)||0);node=defaultNode('text-note',x,y,'');node.name='';node.layer=ed.doc.layers[0]?.id||'layer-main';ed.doc.nodes.push(node);}ed.selected=new Set([node.id]);ed.selectedEdge=null;ed.inlineEditor={nodeId:node.id,before,previousSelection,isNew,baseW:node.w,baseH:node.h};ed.drag=null;renderInspector();drawCanvas();syncInlineTextEditor(true);}
function syncInlineTextEditor(focus=false){const ed=state.editor,host=document.querySelector('#inline-editor-host');if(!host)return;if(!ed?.inlineEditor){host.replaceChildren();host.style.display='none';return;}const info=ed.inlineEditor,node=ed.doc.nodes.find(n=>n.id===info.nodeId);if(!node){finishInlineTextEditor(false);return;}host.style.display='block';let input=host.querySelector('textarea');if(!input){input=document.createElement('textarea');input.className='canvas-inline-editor';input.maxLength=160;input.setAttribute('aria-label','Text on diagram');input.setAttribute('spellcheck','true');input.value=node.name||'';input.addEventListener('input',()=>{const current=state.editor,currentInfo=current?.inlineEditor,editingNode=current?.doc.nodes.find(n=>n.id===currentInfo?.nodeId);if(!currentInfo||!editingNode)return;editingNode.name=input.value;resizeInlineTextNode(editingNode,currentInfo,input.value);drawCanvas();syncInlineTextEditor();});input.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();event.stopPropagation();finishInlineTextEditor(false);}else if(event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();event.stopPropagation();finishInlineTextEditor(true);}});input.addEventListener('blur',()=>{if(state.editor?.inlineEditor)finishInlineTextEditor(true);});host.append(input);}const zoom=ed.camera.zoom,shape=node.type.startsWith('shape-'),note=node.type==='text-note',component=!shape&&!note;input.className='canvas-inline-editor'+(note?' is-note':shape?' is-shape':' is-component')+(node.props?.fontStyle==='handwritten'?' is-handwritten':'');input.style.left=(ed.camera.x+node.x*zoom+(component?38*zoom:0))+'px';input.style.top=(ed.camera.y+node.y*zoom+(component?7*zoom:0))+'px';input.style.width=Math.max(90,(node.w-(component?46:0))*zoom)+'px';input.style.height=Math.max(30,(node.h-(component?14:0))*zoom)+'px';const fontSize=Number(node.props?.fontSize)||(note?18:shape?13:11);input.style.fontSize=Math.max(10,fontSize*zoom)+'px';input.style.color=safeColor(note?(node.props?.color||'#4d4434'):shape?(node.props?.textColor||'#30473c'):'#30473c');input.style.textAlign=component?'left':'center';if(focus){input.focus();input.setSelectionRange(input.value.length,input.value.length);}}
function resizeInlineTextNode(node,info,text){if(!node.type.startsWith('shape-')&&node.type!=='text-note')return;const canvas=document.querySelector('#diagram-canvas'),ctx=canvas?.getContext('2d');if(!ctx)return;const props=node.props||{},fontSize=Number(props.fontSize)||(node.type==='text-note'?18:13),family=props.fontStyle==='handwritten'?'"Segoe Print","Comic Sans MS",cursive':'Inter,system-ui,sans-serif';ctx.font=fontSize+'px '+family;const lines=text.split('\n'),longest=Math.max(0,...lines.map(line=>ctx.measureText(line).width));node.w=Math.max(info.baseW,Math.min(460,Math.max(110,longest+28)));const wrapped=wrapCanvasText(ctx,text||' ',Math.max(30,node.w-24)),lineHeight=fontSize*1.35;node.h=Math.max(info.baseH,Math.min(520,wrapped.length*lineHeight+20));}
function finishInlineTextEditor(commit=true){const ed=state.editor,info=ed?.inlineEditor;if(!ed||!info)return;const input=document.querySelector('#inline-editor-host textarea'),node=ed.doc.nodes.find(n=>n.id===info.nodeId),text=(input?.value??node?.name??'');if(commit&&info.isNew&&!text.trim())commit=false;ed.inlineEditor=null;if(!commit){ed.doc=info.before;ed.selected=new Set(info.previousSelection);ed.selectedEdge=null;}else if(node){node.name=text;commitChanged(info.before);}document.querySelector('#inline-editor-host')?.replaceChildren();if(!commit)renderInspector();drawCanvas();}
function addEdge(source,target,label=''){const edge={id:uid(),source,target,label,style:'solid',direction:'forward',color:'#64748b'};performEdit(doc=>doc.edges.push(edge));state.editor.selected.clear();state.editor.selectedEdge=edge.id;renderInspector();toast('Connection added. Set its label in the inspector.','success');}

function fitToView(){const ed=state.editor,canvas=document.querySelector('#diagram-canvas');if(!ed||!canvas)return;const rect=canvas.getBoundingClientRect();if(!ed.doc.nodes.length){ed.camera={x:rect.width/2,y:rect.height/2,zoom:1};drawCanvas();return;}const b=worldBounds(ed.doc.nodes);const scale=Math.max(.2,Math.min(1.6,(rect.width-110)/(b.maxX-b.minX),(rect.height-100)/(b.maxY-b.minY)));ed.camera.zoom=scale;ed.camera.x=(rect.width-(b.maxX-b.minX)*scale)/2-b.minX*scale;ed.camera.y=(rect.height-(b.maxY-b.minY)*scale)/2-b.minY*scale;drawCanvas();refreshEditorChrome();}
function zoomBy(factor){const ed=state.editor,c=document.querySelector('#diagram-canvas');if(!ed||!c)return;const r=c.getBoundingClientRect(),cx=r.width/2,cy=r.height/2;const wx=(cx-ed.camera.x)/ed.camera.zoom,wy=(cy-ed.camera.y)/ed.camera.zoom;ed.camera.zoom=Math.max(.2,Math.min(2.5,ed.camera.zoom*factor));ed.camera.x=cx-wx*ed.camera.zoom;ed.camera.y=cy-wy*ed.camera.zoom;drawCanvas();refreshEditorChrome();}
function coalesceOps(pending,ops){const list=[...pending];for(const op of ops){if(op.type==='replace'){list.splice(0,list.length,op);continue;}if(list.at(-1)?.type==='replace'){list[list.length-1]={type:'replace',data:state.editor.doc};continue;}const key=op.type.includes('Node')?`n:${op.id||op.node?.id}`:op.type.includes('Edge')?`e:${op.id||op.edge?.id}`:op.type==='setLayers'?'layers':op.type==='setCustomTypes'?'customTypes':null;if(key){const i=list.findIndex(x=>(x.type.includes('Node')?`n:${x.id||x.node?.id}`:x.type.includes('Edge')?`e:${x.id||x.edge?.id}`:x.type==='setLayers'?'layers':x.type==='setCustomTypes'?'customTypes':null)===key);if(i>=0)list[i]=op;else list.push(op);}else list.push(op);}return list;}
function enqueueOps(ops){const ed=state.editor;if(!ops.length)return;ed.pendingOps=coalesceOps(ed.pendingOps,ops);ed.saveError=false;try{localStorage.setItem(ed.draftKey,JSON.stringify({baseRevision:ed.baseRevision,doc:ed.doc,at:Date.now()}));}catch{toast('Local draft storage is full. Export your diagram to keep a backup.','error');}scheduleSave(700);refreshEditorChrome();}
async function loadComments(diagramId){try{const result=await api(`/api/diagrams/${diagramId}/comments`);if(state.editor?.diagramId!==diagramId)return;state.editor.comments=result.comments;drawCanvas();}catch{}}
function syncEndpointControls(){const ed=state.editor,panel=document.querySelector('#inspector-content');if(!ed||!panel||!ed.selectedEdge||panel.querySelector('[data-prop="edge.source"]'))return;const edge=ed.doc.edges.find(e=>e.id===ed.selectedEdge),section=[...panel.querySelectorAll('.inspector-section')].find(e=>e.textContent.trim()==='Endpoints');if(!edge||!section)return;const options=ed.doc.nodes.map(n=>`<option value="${h(n.id)}">${h(n.name)}</option>`).join('');section.insertAdjacentHTML('afterend',`<div class="field"><label>From</label><select data-prop="edge.source">${options}</select></div><div class="field"><label>To</label><select data-prop="edge.target">${options}</select></div>`);panel.querySelector('[data-prop="edge.source"]').value=edge.source;panel.querySelector('[data-prop="edge.target"]').value=edge.target;}
function createCommentAt(point){const ed=state.editor;if(ed.readOnly)return;const node=findNode(point.x,point.y);const anchor=node?{type:'node',nodeId:node.id}:{type:'point',x:Math.round(point.x),y:Math.round(point.y)};modal('Add a comment',node?`Attached to ${node.name}`:'Attached to this area of the canvas',`<form data-form="comment"><input type="hidden" name="anchor" value="${h(JSON.stringify(anchor))}"><div class="field"><label>Comment</label><textarea name="body" rows="4" required maxlength="2000" placeholder="Capture a question, decision, or follow-up…"></textarea></div><div class="form-feedback"></div><div class="modal-foot" style="padding:8px 0 0"><button type="button" class="btn btn-secondary btn-small" data-action="close-modal">Cancel</button><button class="btn btn-primary btn-small">Add comment</button></div></form>`);}
async function showComments(){const ed=state.editor;await loadComments(ed.diagramId);const comments=ed.comments;const body=`<div style="max-height:300px;overflow:auto">${comments.length?comments.map(c=>`<article class="comment"><strong>${h(c.userName)}</strong><small>${dateTime(c.createdAt)}</small><p>${h(c.body)}</p></article>`).join(''):`<div class="empty-state" style="padding:24px 12px"><div class="empty-icon">▤</div><h3>No comments yet</h3><p>Attach a note to a component or a spot on the canvas.</p></div>`}</div><div style="display:flex;gap:8px;margin-top:13px"><button class="btn btn-primary btn-small" data-action="comment-tool">＋ Add a comment</button><button class="btn btn-secondary btn-small" data-action="close-modal">Close</button></div>`;modal('Comments & annotations','Comments stay attached to a component or canvas location.',body);}
async function showVersions(){const ed=state.editor;const result=await api(`/api/diagrams/${ed.diagramId}/versions`);const rows=result.versions.map(v=>`<div class="version-row"><div><strong>Revision ${v.revision}</strong><small>${h(v.userName)} · ${dateTime(v.createdAt)}</small></div><div style="display:flex;gap:6px"><button class="btn btn-secondary btn-small" data-action="preview-version" data-rev="${v.revision}">Inspect</button>${!ed.readOnly?`<button class="btn btn-quiet btn-small" data-action="restore-version" data-rev="${v.revision}">Restore</button>`:''}</div></div>`).join('');modal('Version history','Saved versions are retained for the most recent 40 revisions.',rows||`<div class="inspector-empty">No saved versions yet.</div>`);}
async function inspectVersion(revision){closeModal();const result=await api(`/api/diagrams/${state.editor.diagramId}/versions/${revision}`);const data=result.version.data;const preview=renderSvg(data,{preview:true});const body=`<div style="height:240px;border:1px solid #e2e9e5;border-radius:8px;overflow:hidden;background:#f8faf9">${preview}</div><p class="tiny muted">Revision ${revision} · ${result.version.data.nodes.length} components · ${result.version.data.edges.length} connections · saved ${dateTime(result.version.createdAt)} by ${h(result.version.userName)}</p><div style="display:flex;justify-content:flex-end;gap:8px"><button class="btn btn-secondary btn-small" data-action="versions">Back to history</button>${!state.editor.readOnly?`<button class="btn btn-primary btn-small" data-action="restore-version" data-rev="${revision}">Restore this version</button>`:''}</div>`;modal(`Inspect revision ${revision}`,'This is a saved snapshot. Restore it to make it the current version.',body);}
async function restoreVersion(revision){const ed=state.editor;if(!confirm(`Restore revision ${revision}? This creates a new current revision and keeps your existing history.`))return;const result=await api(`/api/diagrams/${ed.diagramId}/versions/${revision}/restore`,{method:'POST',body:{}});ed.doc=result.data;ed.baseRevision=result.revision;ed.diagram.revision=result.revision;ed.pendingOps=[];ed.conflict=false;ed.saveError=false;ed.undoStack=[];ed.redoStack=[];localStorage.removeItem(ed.draftKey);closeModal();renderInspector();renderLayers();fitToView();refreshEditorChrome();toast(`Revision ${revision} restored as revision ${result.revision}.`,'success');}
function showShareDialog(){if(state.editor.role!=='Owner'){toast('Only a workspace owner can create a share link.','error');return;}modal('Share a view-only link','Anyone with the link can view this diagram until it expires.',`<form data-form="share"><div class="field"><label>Link expires</label><select name="expiresInDays"><option value="7">In 7 days</option><option value="30" selected>In 30 days</option><option value="90">In 90 days</option><option value="0">Never</option></select></div><div class="form-feedback"></div><div class="modal-foot" style="padding:8px 0 0"><button type="button" class="btn btn-secondary btn-small" data-action="close-modal">Cancel</button><button class="btn btn-primary btn-small">Create view link</button></div></form>`);}
function showShareLink(url,expiresAt){modal('View link created','Anyone with this link can view the diagram. They cannot change it.',`<div class="share-url"><input class="input" id="share-link-value" readonly value="${h(url)}"><button class="btn btn-secondary btn-small" data-action="copy-share">Copy</button></div><p class="field-hint" style="margin-top:9px">${expiresAt?`Expires ${dateTime(expiresAt)}.`:'This link does not expire.'} You can revoke it by deleting the share from the database.</p><div class="modal-foot" style="padding:10px 0 0"><button class="btn btn-primary btn-small" data-action="close-modal">Done</button></div>`);}
function showExportMenu(){modal('Export diagram','Choose a format for sharing or documenting this architecture.',`<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px"><button class="btn btn-secondary" data-action="export-svg">▧ SVG vector</button><button class="btn btn-secondary" data-action="export-png">▧ PNG image</button><button class="btn btn-secondary" data-action="export-pdf">▤ Print / PDF</button><button class="btn btn-secondary" data-action="export-json">{ } Editable JSON</button></div><p class="field-hint" style="margin-top:13px">SVG and JSON preserve the complete diagram. Large canvases may take a moment to export.</p><div style="display:flex;justify-content:flex-end;margin-top:10px"><button class="btn btn-quiet btn-small" data-action="close-modal">Close</button></div>`);}
function showMoreEditorMenu(){const ed=state.editor;modal('Diagram tools','History, comments, sharing, and layout controls.',`<div style="display:grid;gap:7px"><button class="btn btn-secondary" data-action="more-versions">◷ Version history</button><button class="btn btn-secondary" data-action="more-comments">▤ Comments & annotations</button><button class="btn btn-secondary" data-action="more-share" ${ed.role==='Owner'?'':'disabled'}>↗ Create view-only link</button><button class="btn btn-secondary" data-action="more-layout" ${ed.readOnly?'disabled':''}>⌘ Auto layout</button><button class="btn btn-secondary" data-action="more-validate">✓ Validate diagram</button></div>`);}
function renderSvg(doc,{preview=false}={}){
  const nodes=doc.nodes||[],edges=doc.edges||[],b=worldBounds(nodes),width=Math.max(300,b.maxX-b.minX),height=Math.max(200,b.maxY-b.minY),nodeById=new Map(nodes.map(n=>[n.id,n])),layers=new Map((doc.layers||[]).map(l=>[l.id,l]));
  const parts=[`<svg xmlns="http://www.w3.org/2000/svg" viewBox="${b.minX} ${b.minY} ${width} ${height}" width="${width}" height="${height}"><defs><marker id="arrow" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto" markerUnits="strokeWidth"><path d="M0,0 L0,6 L9,3 z" fill="#6d7f76"/></marker></defs><rect x="${b.minX}" y="${b.minY}" width="${width}" height="${height}" fill="#f8faf9"/>`];
  for(const e of edges){const a=nodeById.get(e.source),t=nodeById.get(e.target);if(!a||!t||layers.get(a.layer)?.visible===false||layers.get(t.layer)?.visible===false)continue;parts.push(`<line x1="${a.x+a.w/2}" y1="${a.y+a.h/2}" x2="${t.x+t.w/2}" y2="${t.y+t.h/2}" stroke="${safeColor(e.color)}" stroke-width="2" ${e.style==='dashed'?'stroke-dasharray="7 5"':''} ${e.direction==='none'?'':'marker-end="url(#arrow)"'}/>`);if(e.direction==='both')parts.push(`<path d="M${a.x+a.w/2+5} ${a.y+a.h/2-5} l-8 5 8 5" fill="none" stroke="${safeColor(e.color)}" stroke-width="2"/>`);if(e.label)parts.push(`<text x="${(a.x+a.w/2+t.x+t.w/2)/2}" y="${(a.y+a.h/2+t.y+t.h/2)/2-7}" text-anchor="middle" font-family="Inter,Arial,sans-serif" font-size="11" fill="#52665c">${h(e.label)}</text>`);}
  for(const n of nodes){if(layers.get(n.layer)?.visible===false)continue;const p=n.props||{};if(n.type==='freehand'){const points=Array.isArray(p.points)?p.points:[];if(points.length>1)parts.push(`<polyline points="${points.map(q=>`${n.x+q.x},${n.y+q.y}`).join(' ')}" fill="none" stroke="${safeColor(p.stroke||'#2f6d53')}" stroke-width="${Math.max(1,Math.min(16,Number(p.strokeWidth)||3))}" stroke-linecap="round" stroke-linejoin="round"/>`);continue;}if(n.type==='text-note'){if(p.background&&p.background!=='transparent')parts.push(`<rect x="${n.x}" y="${n.y}" width="${n.w}" height="${n.h}" rx="8" fill="${safeColor(p.background)}"/>`);const fs=Math.max(12,Math.min(36,Number(p.fontSize)||18)),family=p.fontStyle==='handwritten'?'Segoe Print, Comic Sans MS, cursive':'Inter,Arial,sans-serif',lines=wrapPlainText(n.name,Math.max(8,Math.floor((n.w-24)/(fs*.58)))),shown=lines.slice(0,Math.max(1,Math.floor((n.h-16)/(fs*1.3))));parts.push(`<text x="${n.x+12}" y="${n.y+12+fs}" font-family="${family}" font-size="${fs}" fill="${safeColor(p.color||'#4d4434')}" ${p.fontStyle==='handwritten'?'font-style="italic"':''}>${shown.map((line,i)=>`<tspan x="${n.x+12}" dy="${i?fs*1.3:0}">${h(line)}</tspan>`).join('')}</text>`);continue;}if(n.type.startsWith('shape-')){const shape=p.shape||n.type.slice(6),fill=safeColor(p.fill||'#f3f8f4'),stroke=safeColor(p.stroke||'#769783');if(shape==='ellipse')parts.push(`<ellipse cx="${n.x+n.w/2}" cy="${n.y+n.h/2}" rx="${n.w/2}" ry="${n.h/2}" fill="${fill}" stroke="${stroke}" stroke-width="1.5"/>`);else if(shape==='diamond')parts.push(`<polygon points="${n.x+n.w/2},${n.y} ${n.x+n.w},${n.y+n.h/2} ${n.x+n.w/2},${n.y+n.h} ${n.x},${n.y+n.h/2}" fill="${fill}" stroke="${stroke}" stroke-width="1.5"/>`);else parts.push(`<rect x="${n.x}" y="${n.y}" width="${n.w}" height="${n.h}" rx="${shape==='rounded'?14:2}" fill="${fill}" stroke="${stroke}" stroke-width="1.5"/>`);const lines=wrapPlainText(n.name,Math.max(8,Math.floor((n.w-24)/7))),maxLines=Math.max(1,Math.floor((n.h-12)/18));parts.push(`<text x="${n.x+n.w/2}" y="${n.y+n.h/2-(Math.min(lines.length,maxLines)-1)*9}" text-anchor="middle" font-family="Inter,Arial,sans-serif" font-size="13" fill="${safeColor(p.textColor||'#30473c')}">${lines.slice(0,maxLines).map((line,i)=>`<tspan x="${n.x+n.w/2}" dy="${i?18:0}">${h(line)}</tspan>`).join('')}</text>`);continue;}const c=componentDefinition(n.type,doc);parts.push(`<g><rect x="${n.x}" y="${n.y}" width="${n.w}" height="${n.h}" rx="9" fill="#fff" stroke="#b8cfc1" stroke-width="1.5"/><rect x="${n.x+10}" y="${n.y+10}" width="27" height="27" rx="7" fill="${safeColor(c.color||'#e8f4ef')}"/><text x="${n.x+23.5}" y="${n.y+29}" text-anchor="middle" font-family="Arial,sans-serif" font-size="14" fill="#35745a">${h(n.icon||c.icon||'◇')}</text><text x="${n.x+46}" y="${n.y+26}" font-family="Inter,Arial,sans-serif" font-size="11" font-weight="650" fill="#30473c">${h(n.name)}</text><text x="${n.x+46}" y="${n.y+45}" font-family="Inter,Arial,sans-serif" font-size="9" fill="#87968e">${h(n.type)}</text>${n.description?`<text x="${n.x+10}" y="${n.y+n.h-10}" font-family="Inter,Arial,sans-serif" font-size="9" fill="#718178">${h(n.description.slice(0,60))}</text>`:''}</g>`);}
  parts.push('</svg>');return parts.join('');
}
function safeColor(value){return /^#[0-9a-fA-F]{6}$/.test(value||'')?value:'#64748b';}
function downloadBlob(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportSvg(){const ed=state.editor,svg=renderSvg(ed.doc);downloadBlob(svg,`${safeFilename(ed.diagram.name)}.svg`,'image/svg+xml');closeModal();toast('SVG export is ready.','success');}
function safeFilename(value){return String(value||'architecture').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'architecture';}
async function exportPng(){const ed=state.editor;closeModal();const svg=renderSvg(ed.doc);const b=worldBounds(ed.doc.nodes);let scale=Math.min(2,Math.sqrt(16000000/(Math.max(1,b.maxX-b.minX)*Math.max(1,b.maxY-b.minY))));const img=new Image();const blob=new Blob([svg],{type:'image/svg+xml'});const u=URL.createObjectURL(blob);try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=u;});const c=document.createElement('canvas');c.width=Math.max(1,Math.ceil((b.maxX-b.minX)*scale));c.height=Math.max(1,Math.ceil((b.maxY-b.minY)*scale));const ctx=c.getContext('2d');ctx.fillStyle='#f8faf9';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);const png=await new Promise(resolve=>c.toBlob(resolve,'image/png'));if(!png)throw new Error('The browser could not create a PNG image.');const a=document.createElement('a');const url=URL.createObjectURL(png);a.href=url;a.download=`${safeFilename(ed.diagram.name)}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('PNG export is ready.','success');}catch(e){toast(e.message||'PNG export failed.','error');}finally{URL.revokeObjectURL(u);}}
function exportPdf(){const ed=state.editor;closeModal();const svg=renderSvg(ed.doc);const w=window.open('','_blank');if(!w){toast('Allow pop-ups to print or save this diagram as a PDF.','error');return;}w.document.write(`<!doctype html><html><head><title>${h(ed.diagram.name)}</title><style>@page{size:landscape;margin:10mm}body{margin:0;font:12px Arial;color:#20342b}h1{font-size:18px;margin:0 0 10px}svg{width:100%;height:auto;max-height:calc(100vh - 60px)}@media print{svg{max-height:none}}</style></head><body><h1>${h(ed.diagram.name)}</h1>${svg}<script>window.onload=()=>setTimeout(()=>window.print(),150)<\/script></body></html>`);w.document.close();}
function exportJson(){const ed=state.editor;downloadBlob(JSON.stringify({format:'archflow-diagram',schemaVersion:1,diagram:{name:ed.diagram.name,data:ed.doc}},null,2),`${safeFilename(ed.diagram.name)}.archflow.json`,'application/json');closeModal();toast('Editable diagram data exported.','success');}
function importDiagram(){if(state.editor?.readOnly)return;importInput.value='';importInput.click();}
function validateImportedDoc(doc){
  if(!doc||doc.schemaVersion!==1||!Array.isArray(doc.nodes)||!Array.isArray(doc.edges)||!Array.isArray(doc.layers))throw new Error('This file is not a supported Archflow diagram (schema version 1).');
  if(doc.nodes.length>10000||doc.edges.length>20000)throw new Error('This diagram exceeds the import limits of 10,000 components or 20,000 connections.');
  const ids=new Set();
  for(const n of doc.nodes){
    if(!n.id||ids.has(n.id)||![n.x,n.y,n.w,n.h].every(Number.isFinite))throw new Error('A component has a duplicate id or invalid position.');ids.add(n.id);
    if(n.type==='freehand'&&(!Array.isArray(n.props?.points)||n.props.points.length<2||n.props.points.length>10000||n.props.points.some(p=>!p||!Number.isFinite(p.x)||!Number.isFinite(p.y)||p.x<0||p.y<0||p.x>n.w+1||p.y>n.h+1)||!Number.isFinite(n.props?.strokeWidth)||n.props.strokeWidth<1||n.props.strokeWidth>16))throw new Error('A freehand stroke has invalid points or stroke width.');
  }
  for(const e of doc.edges)if(!e.id||!ids.has(e.source)||!ids.has(e.target))throw new Error('A connection refers to a component that does not exist.');
  return doc;
}
importInput.addEventListener('change',async()=>{const file=importInput.files?.[0];if(!file)return;try{const parsed=JSON.parse(await file.text());const data=validateImportedDoc(parsed.diagram?.data||parsed.data||parsed);const ed=state.editor;const before=clone(ed.doc);ed.doc=clone(data);ed.undoStack.push(before);ed.redoStack=[];enqueueOps([{type:'replace',data:ed.doc}]);renderInspector();renderLayers();fitToView();toast(`Imported ${data.nodes.length} components and ${data.edges.length} connections.`,'success');}catch(error){toast(`Import failed: ${error.message}`,'error');}});

function showNavigator(){const ed=state.editor;const body=`<div class="field"><label>Find a component</label><input id="navigator-search" placeholder="Search by component name or type…" autocomplete="off"></div><div id="navigator-results" style="max-height:260px;overflow:auto"></div><div class="modal-foot" style="padding:10px 0 0"><button class="btn btn-secondary btn-small" data-action="close-modal">Close</button></div>`;modal('Diagram navigator','Jump to any component on this canvas.',body);document.querySelector('#navigator-search')?.focus();renderNavigatorResults('');}
function renderNavigatorResults(query){const box=document.querySelector('#navigator-results'),ed=state.editor;if(!box||!ed)return;const q=query.toLowerCase();const matches=ed.doc.nodes.filter(n=>!q||`${n.name} ${n.type} ${n.description}`.toLowerCase().includes(q)).slice(0,100);box.innerHTML=matches.length?matches.map(n=>`<button class="side-link" style="width:100%" data-action="jump-node" data-id="${n.id}"><span class="palette-glyph">${h(n.icon||'◇')}</span><span>${h(n.name)} <small class="muted">· ${h(n.type)}</small></span></button>`).join(''):`<div class="inspector-empty">No matching components.</div>`;}
function showAnalysis(){const ed=state.editor,degree=new Map(ed.doc.nodes.map(n=>[n.id,0]));for(const e of ed.doc.edges){if(degree.has(e.source))degree.set(e.source,degree.get(e.source)+1);if(degree.has(e.target))degree.set(e.target,degree.get(e.target)+1);}const disconnected=ed.doc.nodes.filter(n=>degree.get(n.id)===0);const unlabeled=ed.doc.edges.filter(e=>!String(e.label||'').trim());const body=`<div class="notice-card"><strong>${ed.doc.nodes.length} components</strong> and <strong>${ed.doc.edges.length} connections</strong> were checked.</div><div class="inspector-section">Disconnected components · ${disconnected.length}</div>${disconnected.length?disconnected.map(n=>`<div class="version-row"><div>${h(n.name)}<small>${h(n.type)} · no connected relationships</small></div><button class="btn btn-quiet btn-small" data-action="jump-node" data-id="${n.id}">Locate</button></div>`).join(''):`<p class="tiny muted">Every component has at least one connection.</p>`}<div class="inspector-section">Connections without labels · ${unlabeled.length}</div>${unlabeled.length?unlabeled.map(e=>`<div class="version-row"><div>${h(ed.doc.nodes.find(n=>n.id===e.source)?.name||'Component')} → ${h(ed.doc.nodes.find(n=>n.id===e.target)?.name||'Component')}<small>Consider adding protocol or data-flow details.</small></div><button class="btn btn-quiet btn-small" data-action="select-edge" data-id="${e.id}">Edit</button></div>`).join(''):`<p class="tiny muted">All connections have a label.</p>`}<p class="field-hint" style="margin-top:13px">This is a basic diagram check, not a production or security review.</p>`;modal('Diagram validation','Find disconnected components and relationships that need a label.',body);}
function autoLayout(){const ed=state.editor;if(ed.readOnly)return;if(!ed.doc.nodes.length){toast('Add components before using auto layout.');return;}const before=clone(ed.doc),nodes=ed.doc.nodes,indegree=new Map(nodes.map(n=>[n.id,0])),adj=new Map(nodes.map(n=>[n.id,[]]));for(const e of ed.doc.edges){if(adj.has(e.source)&&indegree.has(e.target)){adj.get(e.source).push(e.target);indegree.set(e.target,indegree.get(e.target)+1);}}let roots=nodes.filter(n=>indegree.get(n.id)===0).map(n=>n.id);if(!roots.length)roots=[nodes[0].id];const levels=new Map(roots.map(id=>[id,0])),queue=[...roots];while(queue.length){const id=queue.shift();for(const to of adj.get(id)||[]){if(!levels.has(to)){levels.set(to,(levels.get(id)||0)+1);queue.push(to);}}}for(const n of nodes)if(!levels.has(n.id))levels.set(n.id,Math.max(...levels.values())+1);const groups=new Map();for(const n of nodes){const l=levels.get(n.id);if(!groups.has(l))groups.set(l,[]);groups.get(l).push(n);}for(const [level,list]of groups.entries())list.forEach((n,i)=>{n.x=level*230;n.y=i*130;});commitChanged(before);fitToView();toast('Diagram arranged from left to right.','success');}
function duplicateSelection(){const ed=state.editor;if(ed.readOnly||!ed.selected.size)return;const before=clone(ed.doc),chosen=ed.doc.nodes.filter(n=>ed.selected.has(n.id)),map=new Map(chosen.map(n=>[n.id,uid()]));const copies=chosen.map(n=>({...clone(n),id:map.get(n.id),x:n.x+36,y:n.y+36,name:`${n.name} copy`}));ed.doc.nodes.push(...copies);const edges=ed.doc.edges.filter(e=>map.has(e.source)&&map.has(e.target)).map(e=>({...clone(e),id:uid(),source:map.get(e.source),target:map.get(e.target)}));ed.doc.edges.push(...edges);ed.selected=new Set(copies.map(n=>n.id));commitChanged(before);renderInspector();}
function deleteSelection(){const ed=state.editor;if(ed.readOnly)return;if(ed.selectedEdge){const id=ed.selectedEdge;performEdit(doc=>{doc.edges=doc.edges.filter(e=>e.id!==id);});ed.selectedEdge=null;}else if(ed.selected.size){const selected=new Set(ed.selected);performEdit(doc=>{doc.nodes=doc.nodes.filter(n=>!selected.has(n.id));doc.edges=doc.edges.filter(e=>!selected.has(e.source)&&!selected.has(e.target));});ed.selected.clear();}renderInspector();drawCanvas();}
function copySelection(){const ed=state.editor;if(!ed.selected.size)return;const nodes=ed.doc.nodes.filter(n=>ed.selected.has(n.id));const ids=new Set(nodes.map(n=>n.id));ed.clipboard={nodes:clone(nodes),edges:clone(ed.doc.edges.filter(e=>ids.has(e.source)&&ids.has(e.target)))};toast(`${nodes.length} component${nodes.length===1?'':'s'} copied.`);}
function pasteSelection(){const ed=state.editor;if(!ed.clipboard||ed.readOnly)return;const before=clone(ed.doc),map=new Map(ed.clipboard.nodes.map(n=>[n.id,uid()]));const nodes=ed.clipboard.nodes.map(n=>({...clone(n),id:map.get(n.id),x:n.x+42,y:n.y+42,name:`${n.name} copy`}));const edges=ed.clipboard.edges.map(e=>({...clone(e),id:uid(),source:map.get(e.source),target:map.get(e.target)}));ed.doc.nodes.push(...nodes);ed.doc.edges.push(...edges);ed.selected=new Set(nodes.map(n=>n.id));commitChanged(before);renderInspector();}
function alignSelection(){const ed=state.editor;if(ed.selected.size<2)return;const before=clone(ed.doc),selected=ed.doc.nodes.filter(n=>ed.selected.has(n.id)),center=selected[0].y+selected[0].h/2;for(const n of selected)n.y=center-n.h/2;commitChanged(before);}
function jumpToNode(nodeId){const ed=state.editor,n=ed.doc.nodes.find(n=>n.id===nodeId);if(!n)return;const c=document.querySelector('#diagram-canvas'),r=c.getBoundingClientRect();ed.camera.x=r.width/2-(n.x+n.w/2)*ed.camera.zoom;ed.camera.y=r.height/2-(n.y+n.h/2)*ed.camera.zoom;ed.selected=new Set([nodeId]);ed.selectedEdge=null;closeModal();renderInspector();drawCanvas();}

function openCustomComponent(){modal('Create a component','Add a reusable type with its own icon and custom properties.',`<form data-form="custom-component"><div class="field"><label>Name</label><input name="name" required maxlength="100" placeholder="e.g. Payment processor"></div><div class="field"><label>Description</label><textarea name="description" maxlength="500" placeholder="What does this component represent?"></textarea></div><div class="field"><label>Icon</label><input name="icon" value="✦" maxlength="4"></div><div class="field"><label>Default properties (JSON)</label><textarea name="props" rows="4">{}</textarea></div><div class="form-feedback"></div><div class="modal-foot" style="padding:8px 0 0"><button type="button" class="btn btn-secondary btn-small" data-action="close-modal">Cancel</button><button class="btn btn-primary btn-small">Create component</button></div></form>`);}

function openWorkspaceCreate(){modal('Create a workspace','Keep another team or product’s architecture work in its own space.',`<form data-form="workspace-create"><div class="field"><label>Workspace name</label><input name="name" required maxlength="100" placeholder="e.g. Payments team"></div><div class="form-feedback"></div><div class="modal-foot" style="padding:8px 0 0"><button type="button" class="btn btn-secondary btn-small" data-action="close-modal">Cancel</button><button class="btn btn-primary btn-small">Create workspace</button></div></form>`);}
function makeTemplate(template){const doc=defaultDoc();const specs={
  web:[['client','Web & mobile clients',-360,10],['network','CDN & WAF',-130,10],['api','API gateway',100,10],['service','Application service',330,10],['database','Postgres database',560,-75],['cache','Redis cache',560,95]],
  microservices:[['client','Mobile application',-400,20],['api','API gateway',-170,20],['service','Identity service',80,-130],['service','Catalog service',80,0],['service','Order service',80,130],['database','Customer database',330,-130],['cache','Catalog cache',330,0],['queue','Event bus',330,130],['service','Fulfillment worker',560,130]],
  pipeline:[['external','Partner feeds',-400,20],['service','Ingestion service',-170,20],['queue','Ingest queue',60,20],['function','Transform jobs',290,20],['database','Analytics warehouse',520,20],['web','BI dashboards',750,20]],
};if(template==='blank')return doc;const items=specs[template]||specs.web;const nodes=items.map(([type,name,x,y])=>defaultNode(type,x,y,name));doc.nodes=nodes;const pairs=template==='web'?[[0,1,'HTTPS'],[1,2,'TLS'],[2,3,'REST'],[3,4,'writes'],[3,5,'cache']]:template==='microservices'?[[0,1,'HTTPS'],[1,2,'OAuth'],[1,3,'catalog'],[1,4,'checkout'],[2,5,'users'],[3,6,'read-through'],[4,7,'publishes'],[7,8,'consumes']]:[[0,1,'HTTPS'],[1,2,'publish'],[2,3,'consume'],[3,4,'load'],[4,5,'query']];doc.edges=pairs.map(([a,b,label])=>({id:uid(),source:nodes[a].id,target:nodes[b].id,label,style:'solid',direction:'forward',color:'#64748b'}));return doc;}
async function createDiagramFromTemplate(projectId,template){const name=document.querySelector('#new-diagram-name')?.value?.trim()||'Untitled diagram';const data=makeTemplate(template);try{const result=await api(`/api/projects/${projectId}/diagrams`,{method:'POST',body:{name,data}});closeModal();state.project=null;setRoute(`/diagram/${result.diagram.id}`);}catch(error){toast(error.message,'error');}}

app.addEventListener('click',async(event)=>{
  const el=event.target.closest('[data-action],[data-tool]');if(!el)return;
  if(el.dataset.action==='backdrop'&&event.target!==el)return;
  const action=el.dataset.action,id=el.dataset.id;
  if(el.dataset.tool){setTool(el.dataset.tool);return;}
  try{
    switch(action){
      case 'signin':setRoute('/signin');break;case 'signup':setRoute('/signup');break;case 'forgot':setRoute('/forgot');break;case 'home':setRoute('/');break;
      case 'demo-login':{const r=await api('/api/auth/signin',{method:'POST',body:{email:'demo@archflow.local',password:'Diagram!2026'}});state.user=r.user;const me=await api('/api/me');state.workspaces=me.workspaces;state.workspaceId=me.workspaces[0]?.id||'';localStorage.setItem('archflow.workspace',state.workspaceId);toast('Demo workspace opened.','success');setRoute('/app');break;}
      case 'dashboard':state.dashboardArchived=false;state.dashboardQuery='';setRoute('/app');break;case 'archive':state.dashboardArchived=true;setRoute('/archive');break;
      case 'new-project':openCreateProject();break;case 'open-project':if(!event.target.closest('[data-action="project-menu"]'))setRoute(`/project/${id}`);break;
      case 'project-menu':openProjectMenu(id);break;case 'project-overflow':openProjectMenu(id);break;case 'edit-project':if(state.project?.id!==id)state.project=state.projects.find(p=>p.id===id)||null;if(state.project)openEditProject();else toast('Project could not be loaded.','error');break;
      case 'duplicate-project':{const p=await api(`/api/projects/${id}/duplicate`,{method:'POST',body:{}});closeModal();toast('Project duplicated.','success');setRoute(`/project/${p.project.id}`);break;}
      case 'archive-project':if(confirm('Archive this project? You can restore it later.')){await api(`/api/projects/${id}/archive`,{method:'POST',body:{}});closeModal();toast('Project archived.','success');setRoute('/app');}break;
      case 'restore-project':await api(`/api/projects/${id}/restore`,{method:'POST',body:{}});closeModal();toast('Project restored.','success');setRoute('/app');break;
      case 'delete-project':if(confirm('Delete this project and its diagrams permanently? This cannot be undone.')){await api(`/api/projects/${id}`,{method:'DELETE'});closeModal();toast('Project deleted.','success');setRoute('/app');}break;
      case 'new-diagram':openTemplateModal(id);break;case 'choose-template':await createDiagramFromTemplate(el.dataset.project,el.dataset.id);break;case 'open-diagram':setRoute(`/diagram/${id}`);break;case 'project-back':state.project=null;setRoute(`/project/${id}`);break;
      case 'workspace-menu':workspaceMenu();break;case 'switch-workspace':state.workspaceId=id;localStorage.setItem('archflow.workspace',id);state.dashboardArchived=false;closeModal();setRoute('/app');break;case 'create-workspace':openWorkspaceCreate();break;
      case 'settings':setRoute('/settings');break;case 'settings-account':await renderSettings();break;case 'settings-members':showSettingsMembers();break;case 'settings-workspace':showSettingsWorkspace();break;case 'remove-member':if(confirm('Remove this person from the workspace?')){await api(`/api/workspaces/${state.workspaceId}/members/${id}`,{method:'DELETE'});toast('Member removed.','success');await renderSettings();showSettingsMembers();}break;case 'signout':await api('/api/auth/signout',{method:'POST',body:{}});state.user=null;state.workspaces=[];state.editor=null;state.project=null;closeModal();setRoute('/');break;
      case 'accept-invite':{const accepted=await api(`/api/invitations/${el.dataset.token}/accept`,{method:'POST',body:{}});const me=await api('/api/me');state.user=me.user;state.workspaces=me.workspaces;state.workspaceId=accepted.workspaceId;localStorage.setItem('archflow.workspace',state.workspaceId);toast('You joined the workspace.','success');setRoute('/app');break;}
      case 'close-modal':closeModal();break;case 'backdrop':closeModal();break;case 'clear-search':state.dashboardQuery='';await renderDashboard();break;
      case 'undo':undo();break;case 'redo':redo();break;case 'zoom-in':zoomBy(1.15);break;case 'zoom-out':zoomBy(.87);break;case 'zoom-label':fitToView();break;case 'fit':fitToView();break;case 'grid-toggle':{const ed=state.editor;ed.grid=!ed.grid;document.querySelector('#canvas-wrap').classList.toggle('grid-dots',ed.grid&&ed.gridStyle==='dots');document.querySelector('#canvas-wrap').classList.toggle('grid-lines',ed.grid&&ed.gridStyle==='lines');el.classList.toggle('active',ed.grid);break;}case 'snap-toggle':{const ed=state.editor;ed.snap=!ed.snap;el.classList.toggle('active',ed.snap);el.title=`Snap to grid: ${ed.snap?'on':'off'}`;break;}
      case 'toggle-palette':document.querySelector('#palette')?.classList.toggle('open');break;case 'add-component':addNode(el.dataset.type);break;case 'custom-component':openCustomComponent();break;case 'clear-selection':state.editor.selected.clear();state.editor.selectedEdge=null;renderInspector();drawCanvas();break;
      case 'delete-selection':deleteSelection();break;case 'duplicate-selection':duplicateSelection();break;case 'edit-text-note':{const note=state.editor.doc.nodes.find(n=>state.editor.selected.has(n.id));if(note)startInlineTextEditor({x:note.x,y:note.y},note.id);break;}case 'align-selection':alignSelection();break;case 'group-selection':if(state.editor.selected.size>1){modal('Group selected components','Give this visual group a name.',`<form data-form="group"><div class="field"><label>Group name</label><input name="name" required maxlength="80" placeholder="e.g. Private subnet"></div><div class="form-feedback"></div><div class="modal-foot" style="padding:8px 0 0"><button type="button" class="btn btn-secondary btn-small" data-action="close-modal">Cancel</button><button class="btn btn-primary btn-small">Group components</button></div></form>`);}break;
      case 'layer-visible':performEdit(doc=>{const l=doc.layers.find(l=>l.id===id);if(l)l.visible=l.visible===false;});break;case 'layer-lock':performEdit(doc=>{const l=doc.layers.find(l=>l.id===id);if(l)l.locked=!l.locked;});break;
      case 'layer-move':performEdit(doc=>{const i=doc.layers.findIndex(l=>l.id===id),j=i+Number(el.dataset.dir);if(i>=0&&j>=0&&j<doc.layers.length)[doc.layers[i],doc.layers[j]]=[doc.layers[j],doc.layers[i]];});break;
      case 'add-layer':modal('Add a layer','Organize the diagram into visual sections.',`<form data-form="layer"><div class="field"><label>Layer name</label><input name="name" required maxlength="60" placeholder="e.g. Data plane"></div><div class="form-feedback"></div><div class="modal-foot" style="padding:8px 0 0"><button type="button" class="btn btn-secondary btn-small" data-action="close-modal">Cancel</button><button class="btn btn-primary btn-small">Add layer</button></div></form>`);break;
      case 'versions':closeModal();await showVersions();break;case 'preview-version':await inspectVersion(Number(el.dataset.rev));break;case 'restore-version':await restoreVersion(Number(el.dataset.rev));break;case 'share':showShareDialog();break;case 'comments':await showComments();if(state.editor.readOnly)document.querySelector('[data-action="comment-tool"]')?.remove();break;case 'comment-tool':if(state.editor.readOnly){toast('View-only access cannot add comments.','error');break;}closeModal();setTool('comment');toast('Click a component or a location on the canvas to attach your comment.');break;case 'more-editor':showMoreEditorMenu();break;case 'more-versions':closeModal();await showVersions();break;case 'more-comments':closeModal();await showComments();if(state.editor.readOnly)document.querySelector('[data-action="comment-tool"]')?.remove();break;case 'more-share':closeModal();showShareDialog();break;case 'more-layout':closeModal();autoLayout();break;case 'more-validate':closeModal();showAnalysis();break;
      case 'export-menu':showExportMenu();break;case 'export-svg':exportSvg();break;case 'export-png':await exportPng();break;case 'export-pdf':exportPdf();break;case 'export-json':exportJson();break;case 'import':importDiagram();break;
      case 'analyze':showAnalysis();break;case 'auto-layout':autoLayout();break;case 'navigator':showNavigator();break;case 'jump-node':jumpToNode(id);break;case 'select-edge':{state.editor.selected.clear();state.editor.selectedEdge=id;closeModal();renderInspector();drawCanvas();break;}
      case 'copy-share':{const input=document.querySelector('#share-link-value');await navigator.clipboard?.writeText(input.value);input.select();if(!navigator.clipboard)document.execCommand('copy');toast('Share link copied.','success');break;}
      case 'download-local-draft':{const ed=state.editor;downloadBlob(JSON.stringify({format:'archflow-diagram',schemaVersion:1,diagram:{name:ed.diagram.name,data:ed.localConflictDoc||ed.doc}},null,2),`${safeFilename(ed.diagram.name)}-local-draft.json`,'application/json');break;}
      case 'reload-remote':if(confirm('Load the latest server version? Your local draft will remain downloadable until you close this diagram.')){const ed=state.editor;const result=await api(`/api/diagrams/${ed.diagramId}`);ed.doc=result.diagram.data;ed.diagram=result.diagram;ed.baseRevision=result.diagram.revision;ed.pendingOps=[];ed.conflict=false;ed.saveError=false;ed.undoStack=[];ed.redoStack=[];localStorage.removeItem(ed.draftKey);document.querySelector('#conflict-banner')?.remove();renderInspector();renderLayers();fitToView();refreshEditorChrome();toast('Latest server version loaded.','success');}break;
      case 'help':modal('Keyboard shortcuts','Work quickly without leaving the canvas.',`<div class="property-row"><span>Select tool</span><strong>V</strong></div><div class="property-row"><span>Connect tool</span><strong>C</strong></div><div class="property-row"><span>Pen tool</span><strong>P</strong></div><div class="property-row"><span>Text tool</span><strong>T</strong></div><div class="property-row"><span>Box tool</span><strong>B</strong></div><div class="property-row"><span>Pan canvas</span><strong>Space + drag</strong></div><div class="property-row"><span>Undo / redo</span><strong>Ctrl/⌘ Z / Shift Z</strong></div><div class="property-row"><span>Duplicate</span><strong>Ctrl/⌘ D</strong></div><div class="property-row"><span>Copy / paste</span><strong>Ctrl/⌘ C / V</strong></div><div class="property-row"><span>Delete selection</span><strong>Delete / Backspace</strong></div><div class="property-row"><span>Fit to view</span><strong>F</strong></div>`);break;
    }
  }catch(error){toast(error.message||'Something went wrong.','error');}
});

document.addEventListener('submit',async(event)=>{const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();const values=Object.fromEntries(new FormData(form).entries());const feedback=form.querySelector('.form-feedback');if(feedback){feedback.className='form-feedback';feedback.textContent='';}
  const showError=(message)=>{if(feedback){feedback.className='form-feedback form-error';feedback.textContent=message;}else toast(message,'error');};
  const showSuccess=(message)=>{if(feedback){feedback.className='form-feedback form-success';feedback.textContent=message;}else toast(message,'success');};
  try{
    switch(form.dataset.form){
      case 'signup':{const result=await api('/api/auth/signup',{method:'POST',body:values});state.user=result.user;const me=await api('/api/me');state.workspaces=me.workspaces;state.workspaceId=me.workspaces[0]?.id||'';localStorage.setItem('archflow.workspace',state.workspaceId);toast('Your workspace is ready.','success');setRoute('/app');break;}
      case 'signin':{const result=await api('/api/auth/signin',{method:'POST',body:values});state.user=result.user;const me=await api('/api/me');state.workspaces=me.workspaces;state.workspaceId=me.workspaces[0]?.id||'';localStorage.setItem('archflow.workspace',state.workspaceId);setRoute('/app');break;}
      case 'forgot':await api('/api/auth/forgot',{method:'POST',body:values}).then(r=>showSuccess(r.message));break;
      case 'reset':await api('/api/auth/reset',{method:'POST',body:{token:values.token,password:values.password}});toast('Password updated. Sign in with your new password.','success');setRoute('/signin');break;
      case 'project':{const tags=values.tags.split(',').map(t=>t.trim()).filter(Boolean);let result;if(values.id)result=await api(`/api/projects/${values.id}`,{method:'PATCH',body:{name:values.name,description:values.description,tags}});else result=await api('/api/projects',{method:'POST',body:{workspaceId:state.workspaceId,name:values.name,description:values.description,tags}});closeModal();toast(values.id?'Project updated.':'Project created.','success');state.project=result.project;setRoute(`/project/${result.project.id}`);break;}
      case 'profile':{const result=await api('/api/profile',{method:'PATCH',body:{name:values.name}});state.user={...state.user,name:result.user.name};toast('Profile updated.','success');await renderSettings();break;}
      case 'password':await api('/api/profile/password',{method:'POST',body:values});form.reset();showSuccess('Password updated.');break;
      case 'workspace-create':{const result=await api('/api/workspaces',{method:'POST',body:values});state.workspaces.push(result.workspace);state.workspaceId=result.workspace.id;localStorage.setItem('archflow.workspace',state.workspaceId);closeModal();toast('Workspace created.','success');setRoute('/app');break;}
      case 'workspace-rename':{const result=await api(`/api/workspaces/${state.workspaceId}`,{method:'PATCH',body:values});state.workspaces=state.workspaces.map(w=>w.id===state.workspaceId?{...w,name:result.workspace.name}:w);showSuccess('Workspace name updated.');await renderSettings();break;}
      case 'invite':{const result=await api(`/api/workspaces/${state.workspaceId}/invitations`,{method:'POST',body:values});const feedbackBox=document.querySelector('#invite-feedback');if(feedbackBox){feedbackBox.className='form-success';feedbackBox.innerHTML=`Invitation created for ${h(result.invitation.email)}. Copy this link to share it: <button class="text-link" data-action="copy-invitation" data-url="${h(result.invitation.acceptUrl)}" style="border:0;background:none">Copy invitation link</button><div style="word-break:break-all;margin-top:6px">${h(result.invitation.acceptUrl)}</div>`;}form.reset();break;}
      case 'text-annotation':{const ed=state.editor,text=values.text.trim();if(!text){showError('Enter some text for this annotation.');return;}const fontSize=Math.max(12,Math.min(36,Number(values.fontSize)||18)),nodeId=values.nodeId,existing=nodeId?ed.doc.nodes.find(n=>n.id===nodeId):null,before=clone(ed.doc);let node=existing;if(!node){const x=Number(values.x)||0,y=Number(values.y)||0;node=defaultNode('text-note',ed.snap?Math.round(x/20)*20:x,ed.snap?Math.round(y/20)*20:y,text);node.layer=ed.doc.layers[0]?.id||'layer-main';ed.doc.nodes.push(node);}node.name=text;node.props={...(node.props||{}),fontStyle:values.fontStyle==='standard'?'standard':'handwritten',fontSize,color:node.props?.color||'#4d4434',background:values.background==='none'?'transparent':'#fff7e5'};if(!existing){const longest=Math.max(...text.split('\n').map(line=>line.length),1),lines=Math.max(1,Math.ceil(longest/30));node.w=Math.max(160,Math.min(460,Math.ceil(longest*fontSize*.58+28)));node.h=Math.max(42,Math.min(320,Math.ceil(lines*fontSize*1.4+20)));}ed.selected=new Set([node.id]);ed.selectedEdge=null;commitChanged(before);closeModal();renderInspector();toast('Text annotation saved.','success');break;}
      case 'group':{const name=values.name.trim();performEdit(doc=>{for(const n of doc.nodes)if(state.editor.selected.has(n.id))n.group=name;});closeModal();toast('Components grouped.','success');break;}
      case 'layer':{const name=values.name.trim();performEdit(doc=>doc.layers.push({id:uid(),name,visible:true,locked:false}));closeModal();break;}
      case 'custom-component':{let props={};try{props=JSON.parse(values.props||'{}');if(!props||typeof props!=='object'||Array.isArray(props))throw new Error();}catch{showError('Properties must be a valid JSON object.');return;}const type=`custom-${uid().slice(0,8)}`,definition={type,name:values.name.trim(),description:values.description.trim(),icon:values.icon.trim()||'✦',props};const before=clone(state.editor.doc);state.editor.doc.customTypes.push(definition);const rect=document.querySelector('#diagram-canvas').getBoundingClientRect(),p=screenToWorld(rect.left+rect.width/2,rect.top+rect.height/2);const node={...defaultNode(type,p.x,p.y,definition.name),description:definition.description,props:clone(props)};state.editor.doc.nodes.push(node);state.editor.selected=new Set([node.id]);commitChanged(before);renderPalette();closeModal();renderInspector();toast('Custom component created.','success');break;}
      case 'share':{const days=Number(values.expiresInDays);const result=await api(`/api/diagrams/${state.editor.diagramId}/share`,{method:'POST',body:{expiresInDays:days===0?null:days}});showShareLink(result.url,result.expiresAt);break;}
      case 'comment':{const anchor=JSON.parse(values.anchor);const result=await api(`/api/diagrams/${state.editor.diagramId}/comments`,{method:'POST',body:{anchor,body:values.body}});state.editor.comments.push(result.comment);closeModal();drawCanvas();toast('Comment added.','success');break;}
    }
  }catch(error){showError(error.message||'Could not save this form.');}
});

document.addEventListener('input',(event)=>{
  const input=event.target;
  if(input.matches('[data-input="dashboard-search"]')){state.dashboardQuery=input.value;clearTimeout(state.searchTimer);state.searchTimer=setTimeout(()=>renderDashboard().catch(e=>toast(e.message,'error')),280);return;}
  if(input.matches('[data-input="palette-search"]')){if(!state.editor)return;state.editor.paletteQuery=input.value;renderPalette();return;}
  if(input.id==='navigator-search'){renderNavigatorResults(input.value);return;}
  const prop=input.dataset.prop;if(!prop||!state.editor||state.editor.readOnly)return;
  if(input.dataset.commitOnChange==='true')return;
  if(prop==='node.props')return;
  updateProperty(prop,input);
});
document.addEventListener('change',(event)=>{
  const input=event.target;
  if(input.matches('[data-input="project-sort"]')){state.dashboardSort=input.value;renderDashboard().catch(e=>toast(e.message,'error'));return;}
  if(input.matches('[data-input="member-role"]')){api(`/api/workspaces/${state.workspaceId}/members/${input.dataset.id}`,{method:'PATCH',body:{role:input.value}}).then(()=>{toast('Member role updated.','success');return renderSettings().then(showSettingsMembers);}).catch(e=>toast(e.message,'error'));return;}
  const prop=input.dataset.prop;if(!prop||!state.editor||state.editor.readOnly)return;
  if(prop==='node.props'){try{const parsed=JSON.parse(input.value||'{}');if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))throw new Error();updateProperty(prop,input,parsed);}catch{toast('Properties must be a valid JSON object.','error');input.value=JSON.stringify(state.editor.doc.nodes.find(n=>state.editor.selected.has(n.id))?.props||{},null,2);}return;}
  if(prop.startsWith('node.')||prop.startsWith('edge.'))updateProperty(prop,input);
  if(input.matches('#diagram-title'))saveDiagramTitle(input.value);
});
function updateProperty(prop,input,parsed){const ed=state.editor;if(!ed||ed.readOnly)return;const edge=prop.startsWith('edge.'),node=prop.startsWith('node.');if(!edge&&!node)return;const before=clone(ed.doc);const key=prop.split('.')[1];let value=input.type==='checkbox'?input.checked:input.type==='number'?Number(input.value):input.value;if(key==='props')value=parsed;if(key==='w')value=Math.max(36,value);if(key==='h')value=Math.max(28,value);if(key==='strokeWidth')value=Math.max(1,Math.min(16,value));if(key==='fontSize')value=Math.max(12,Math.min(36,value));if(edge){const item=ed.doc.edges.find(e=>e.id===ed.selectedEdge);if(!item)return;item[key]=value;}else{const item=ed.doc.nodes.find(n=>ed.selected.has(n.id));if(!item)return;if(['shape','fill','stroke','textColor','fontStyle','fontSize','color','background','strokeWidth'].includes(key)){item.props=item.props||{};item.props[key]=value;}else item[key]=value;}commitChanged(before);}
async function saveDiagramTitle(value){const ed=state.editor;if(!ed||ed.readOnly||!value.trim())return;clearTimeout(ed.titleTimer);ed.titleTimer=setTimeout(async()=>{try{const result=await api(`/api/diagrams/${ed.diagramId}`,{method:'PATCH',body:{name:value.trim()}});ed.diagram.name=result.name;toast('Diagram name saved.','success');}catch(error){toast(error.message,'error');}},500);}

document.addEventListener('click',(event)=>{const button=event.target.closest('[data-action="copy-invitation"]');if(!button)return;const value=button.dataset.url;navigator.clipboard?.writeText(value).then(()=>toast('Invitation link copied.','success')).catch(()=>toast(value));});
document.addEventListener('keydown',(event)=>{
  const ed=state.editor;if(!ed)return;const target=event.target;const typing=target.matches('input,textarea,select,[contenteditable="true"]');const mod=event.ctrlKey||event.metaKey;
  if(event.code==='Space'&&!typing){event.preventDefault();ed.spaceDown=true;return;}
  if(typing)return;
  if(mod&&event.key.toLowerCase()==='z'){event.preventDefault();event.shiftKey?redo():undo();return;}
  if(mod&&event.key.toLowerCase()==='y'){event.preventDefault();redo();return;}
  if(mod&&event.key.toLowerCase()==='d'){event.preventDefault();if(!ed.selected.size)return;duplicateSelection();return;}
  if(mod&&event.key.toLowerCase()==='c'){event.preventDefault();copySelection();return;}
  if(mod&&event.key.toLowerCase()==='v'){event.preventDefault();pasteSelection();return;}
  if(event.key==='Delete'||event.key==='Backspace'){event.preventDefault();deleteSelection();return;}
  if(event.key.toLowerCase()==='v')setTool('select');if(event.key.toLowerCase()==='c')setTool('connect');if(event.key.toLowerCase()==='p')setTool('pen');if(event.key.toLowerCase()==='t')setTool('text');if(event.key.toLowerCase()==='b')setTool('box');if(event.key.toLowerCase()==='f')fitToView();if(event.key==='Escape'){if(state.modal)closeModal();else{ed.selected.clear();ed.selectedEdge=null;setTool('select');renderInspector();drawCanvas();}}
});
document.addEventListener('keyup',(event)=>{if(event.code==='Space'&&state.editor){state.editor.spaceDown=false;if(state.editor.tool==='pan')document.querySelector('#diagram-canvas').style.cursor='grab';}});
window.addEventListener('beforeunload',(event)=>{if(state.editor&&(state.editor.pendingOps.length||state.editor.saving)){event.preventDefault();event.returnValue='';}});

async function boot(){try{await renderRoute();}catch(error){app.innerHTML=`<div class="page-loading"><div class="empty-icon">!</div><h2>Archflow could not start</h2><p>${h(error.message)}</p><button class="btn btn-secondary" onclick="location.reload()">Try again</button></div>`;}}
boot();
